namespace BatchRenameStudio.Core;

/// <summary>Which part of the file name the steps operate on.</summary>
public enum ApplyTo
{
    Name,
    NameAndExtension,
}

/// <summary>Processing order of the files in the folder.</summary>
public enum SortMode
{
    Name,
    Created,
    Modified,
}

public enum StepOp
{
    Replace,
    Insert,
    Remove,
    Sequence,
    Case,
    Extension,
}

public enum InsertPosition
{
    Prefix,
    Suffix,
    Index,
}

public enum SequencePosition
{
    Prefix,
    Suffix,
}

public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>
/// One step of a rule set. A single mutable class carries the union of all six
/// operations' fields; only the fields relevant to <see cref="Op"/> are read.
/// That keeps the GUI editor, the JSON reader and the engine on one shape.
/// </summary>
public sealed class RuleStep
{
    public StepOp Op { get; set; } = StepOp.Replace;

    /// <summary>
    /// GUI-only convenience: a step can be muted without deleting it.
    /// Absent from the JSON contract; defaults to true when the key is missing.
    /// </summary>
    public bool Enabled { get; set; } = true;

    // replace
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    // insert
    public string Text { get; set; } = string.Empty;
    public InsertPosition InsertPosition { get; set; } = InsertPosition.Prefix;
    public int Index { get; set; }

    // remove
    public int From { get; set; }
    public int Count { get; set; }

    // sequence
    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;
    public SequencePosition SequencePosition { get; set; } = SequencePosition.Prefix;

    // case
    public CaseMode CaseMode { get; set; } = CaseMode.Upper;

    // extension
    public ExtensionMode ExtensionMode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public RuleStep Clone() => (RuleStep)MemberwiseClone();

    /// <summary>One-line human summary used by the step list in the GUI.</summary>
    public string Describe()
    {
        switch (Op)
        {
            case StepOp.Replace:
                var mode = Regex ? "regex" : "text";
                var ic = IgnoreCase ? ", ignore case" : string.Empty;
                return $"Replace ({mode}{ic}): \"{Find}\" → \"{ReplaceWith}\"";
            case StepOp.Insert:
                return InsertPosition switch
                {
                    InsertPosition.Prefix => $"Insert \"{Text}\" at start",
                    InsertPosition.Suffix => $"Insert \"{Text}\" at end",
                    _ => $"Insert \"{Text}\" at index {Index}",
                };
            case StepOp.Remove:
                return $"Remove {Count} char(s) from index {From}";
            case StepOp.Sequence:
                var where = SequencePosition == SequencePosition.Prefix ? "start" : "end";
                return $"Number \"{Pattern}\" at {where} (start {Start}, step {Step})";
            case StepOp.Case:
                return $"Case: {CaseMode.ToString().ToLowerInvariant()}";
            case StepOp.Extension:
                return ExtensionMode == ExtensionMode.Set
                    ? $"Extension: set to \"{Value}\""
                    : $"Extension: {ExtensionMode.ToString().ToLowerInvariant()}";
            default:
                return Op.ToString();
        }
    }
}

/// <summary>A complete rule set: scope, processing order and the ordered steps.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var step in Steps)
        {
            copy.Steps.Add(step.Clone());
        }

        return copy;
    }
}

/// <summary>Thrown when a rules document cannot be understood.</summary>
public sealed class RuleFormatException : Exception
{
    public RuleFormatException(string message) : base(message)
    {
    }
}

