namespace BatchRenameStudio.Core;

/// <summary>
/// The contract's name split: <c>dot</c> is the index of the LAST '.' in the
/// file name. When <c>dot &gt; 0</c> the base is name[0..dot) and the extension
/// is name[dot+1..] (WITHOUT the dot); otherwise the whole name is the base and
/// the extension is empty. So ".gitignore" has base ".gitignore" and ext "".
/// </summary>
public readonly struct NameParts
{
    public NameParts(string baseName, string extension)
    {
        Base = baseName;
        Extension = extension;
    }

    public string Base { get; }

    /// <summary>Extension without the leading dot. Empty when there is none.</summary>
    public string Extension { get; }

    public static NameParts Split(string fileName)
    {
        var dot = fileName.LastIndexOf('.');
        if (dot > 0)
        {
            return new NameParts(fileName.Substring(0, dot), fileName.Substring(dot + 1));
        }

        return new NameParts(fileName, string.Empty);
    }

    /// <summary>Reassembly per contract rule 12.</summary>
    public string Compose() =>
        Extension.Length == 0 ? Base : Base + "." + Extension;

    public NameParts WithBase(string baseName) => new(baseName, Extension);

    public NameParts WithExtension(string extension) => new(Base, extension);
}

