using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// Pure string transformations for the six operations. No file system access,
/// no culture sensitivity: every comparison and casing call is ordinal or
/// invariant so that the same inputs always produce the same output.
/// </summary>
public static class StepEngine
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);

    private static readonly Regex SequenceToken =
        new(@"\{n:(0+)\}", RegexOptions.CultureInvariant | RegexOptions.Compiled);

    /// <summary>
    /// Applies every enabled step of <paramref name="rules"/> to one file name.
    /// <paramref name="ordinal"/> is the 0-based position of the file in
    /// processing order and drives the sequence counter.
    /// </summary>
    public static string ApplyAll(string fileName, RuleSet rules, int ordinal)
    {
        if (rules.ApplyTo == ApplyTo.NameAndExtension)
        {
            var whole = fileName;
            foreach (var step in rules.Steps)
            {
                if (!step.Enabled)
                {
                    continue;
                }

                whole = step.Op == StepOp.Extension
                    ? ApplyExtensionToWhole(whole, step)
                    : ApplyToTarget(whole, step, ordinal);
            }

            // Rule 12: under nameAndExtension the target string IS the proposed name.
            return whole;
        }

        var parts = NameParts.Split(fileName);
        foreach (var step in rules.Steps)
        {
            if (!step.Enabled)
            {
                continue;
            }

            parts = step.Op == StepOp.Extension
                ? parts.WithExtension(ApplyExtension(parts.Extension, step))
                : parts.WithBase(ApplyToTarget(parts.Base, step, ordinal));
        }

        return parts.Compose();
    }

    /// <summary>Counter value for the file at <paramref name="ordinal"/>.</summary>
    public static int SequenceValue(RuleStep step, int ordinal) => step.Start + (step.Step * ordinal);

    /// <summary>Applies a non-extension step to the current target string.</summary>
    public static string ApplyToTarget(string target, RuleStep step, int ordinal) => step.Op switch
    {
        StepOp.Replace => ApplyReplace(target, step),
        StepOp.Insert => ApplyInsert(target, step),
        StepOp.Remove => ApplyRemove(target, step),
        StepOp.Sequence => ApplySequence(target, step, ordinal),
        StepOp.Case => ApplyCase(target, step),
        StepOp.Extension => target, // handled by the caller
        _ => target,
    };

    private static string ApplyReplace(string target, RuleStep step)
    {
        if (step.Find.Length == 0)
        {
            // An empty needle has no well-defined "all occurrences"; treat as a no-op.
            return target;
        }

        if (step.Regex)
        {
            var options = RegexOptions.CultureInvariant;
            if (step.IgnoreCase)
            {
                options |= RegexOptions.IgnoreCase;
            }

            try
            {
                return Regex.Replace(target, step.Find, step.ReplaceWith, options, RegexTimeout);
            }
            catch (RegexMatchTimeoutException)
            {
                return target;
            }
        }

        var comparison = step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        return target.Replace(step.Find, step.ReplaceWith, comparison);
    }

    private static string ApplyInsert(string target, RuleStep step)
    {
        switch (step.InsertPosition)
        {
            case InsertPosition.Prefix:
                return step.Text + target;
            case InsertPosition.Suffix:
                return target + step.Text;
            default:
                var at = Math.Clamp(step.Index, 0, target.Length);
                return target.Insert(at, step.Text);
        }
    }

    private static string ApplyRemove(string target, RuleStep step)
    {
        var from = Math.Clamp(step.From, 0, target.Length);
        var count = Math.Clamp(step.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    private static string ApplySequence(string target, RuleStep step, int ordinal)
    {
        var rendered = RenderSequence(step, SequenceValue(step, ordinal));
        return step.SequencePosition == SequencePosition.Suffix
            ? target + rendered
            : rendered + target;
    }

    /// <summary>
    /// Renders the pattern, substituting <c>{n:000}</c> with the zero-padded
    /// counter. A pattern without a token is used verbatim.
    /// </summary>
    public static string RenderSequence(RuleStep step, int value) =>
        SequenceToken.Replace(
            step.Pattern,
            m => value.ToString(new string('0', m.Groups[1].Value.Length), CultureInfo.InvariantCulture));

    private static string ApplyCase(string target, RuleStep step) => step.CaseMode switch
    {
        CaseMode.Upper => target.ToUpperInvariant(),
        CaseMode.Lower => target.ToLowerInvariant(),
        _ => ToTitle(target),
    };

    /// <summary>
    /// For every maximal run of Unicode letters: first character uppercased,
    /// the rest lowercased. Everything else is copied through untouched.
    /// </summary>
    private static string ToTitle(string target)
    {
        var sb = new StringBuilder(target.Length);
        var inRun = false;
        foreach (var ch in target)
        {
            if (char.IsLetter(ch))
            {
                sb.Append(inRun ? char.ToLowerInvariant(ch) : char.ToUpperInvariant(ch));
                inRun = true;
            }
            else
            {
                sb.Append(ch);
                inRun = false;
            }
        }

        return sb.ToString();
    }

    /// <summary>Transforms an extension (no leading dot) per an extension step.</summary>
    public static string ApplyExtension(string extension, RuleStep step) => step.ExtensionMode switch
    {
        ExtensionMode.Lower => extension.ToLowerInvariant(),
        ExtensionMode.Upper => extension.ToUpperInvariant(),
        _ => step.Value,
    };

    /// <summary>
    /// Rule 11/12 under <c>applyTo:"nameAndExtension"</c>: the extension step
    /// applies to the trailing extension of the current whole string.
    /// </summary>
    private static string ApplyExtensionToWhole(string whole, RuleStep step)
    {
        var parts = NameParts.Split(whole);
        return parts.WithExtension(ApplyExtension(parts.Extension, step)).Compose();
    }
}

