using System.Collections.Frozen;

namespace BatchRenameStudio.Core;

/// <summary>Contract rule 13, first bullet: what makes a proposed name invalid.</summary>
public static class NameValidator
{
    private static readonly char[] ForbiddenChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly FrozenSet<string> ReservedDeviceNames = BuildReserved();

    public const int MaxNameLength = 255;

    /// <summary>
    /// Returns true when the name is usable. <paramref name="reason"/> carries a
    /// short human-readable explanation when it is not.
    /// </summary>
    public static bool IsValid(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "empty name";
            return false;
        }

        if (proposed.Length > MaxNameLength)
        {
            reason = $"name longer than {MaxNameLength} characters";
            return false;
        }

        foreach (var ch in proposed)
        {
            if (ch < ' ')
            {
                reason = "control character in name";
                return false;
            }

            if (Array.IndexOf(ForbiddenChars, ch) >= 0)
            {
                reason = $"illegal character '{ch}'";
                return false;
            }
        }

        var baseName = NameParts.Split(proposed).Base;
        if (ReservedDeviceNames.Contains(baseName))
        {
            reason = $"reserved device name '{baseName}'";
            return false;
        }

        reason = string.Empty;
        return true;
    }

    private static FrozenSet<string> BuildReserved()
    {
        var names = new List<string> { "CON", "PRN", "AUX", "NUL" };
        for (var i = 1; i <= 9; i++)
        {
            names.Add("COM" + i);
            names.Add("LPT" + i);
        }

        return names.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
    }
}

