namespace BatchRenameStudio.Core;

/// <summary>
/// Contract rule 1: only regular files directly inside the folder,
/// non-recursive; directories are excluded entirely.
/// </summary>
public static class FileScanner
{
    public static List<FileEntry> Scan(string directory)
    {
        var info = new DirectoryInfo(directory);
        if (!info.Exists)
        {
            throw new DirectoryNotFoundException($"Folder not found: {directory}");
        }

        var entries = new List<FileEntry>();
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            // EnumerateFiles never yields directories; a directory reparse point
            // is not a file either, so nothing further needs excluding here.
            entries.Add(new FileEntry(file.Name, file.CreationTimeUtc, file.LastWriteTimeUtc, file.Length));
        }

        return entries;
    }

    /// <summary>
    /// Contract rule 5. "name" is ordinal (codepoint) ascending and
    /// case-sensitive; the timestamp orders fall back to the same ordinal
    /// comparison on ties so that the plan is deterministic (rule 15).
    /// </summary>
    public static List<FileEntry> Sort(IEnumerable<FileEntry> entries, SortMode mode)
    {
        var list = entries.ToList();
        Comparison<FileEntry> comparison = mode switch
        {
            SortMode.Created => (a, b) =>
            {
                var c = a.CreatedUtc.CompareTo(b.CreatedUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            SortMode.Modified => (a, b) =>
            {
                var c = a.ModifiedUtc.CompareTo(b.ModifiedUtc);
                return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
            },
            _ => (a, b) => string.CompareOrdinal(a.Name, b.Name),
        };

        // List.Sort is unstable, but every comparison above is a total order on
        // distinct file names, so the result is still deterministic.
        list.Sort(comparison);
        return list;
    }
}

