namespace BatchRenameStudio.Core;

/// <summary>
/// Turns a folder scan plus a rule set into a <see cref="RenamePlan"/>.
/// This is the single implementation of the contract; the headless
/// <c>--plan</c> mode and the GUI preview both go through it.
/// </summary>
public static class PlanBuilder
{
    public static RenamePlan Build(string directory, RuleSet rules)
    {
        var scanned = FileScanner.Scan(directory);
        return Build(scanned, rules);
    }

    public static RenamePlan Build(IReadOnlyList<FileEntry> files, RuleSet rules)
    {
        var ordered = FileScanner.Sort(files, rules.Sort);

        // Pass 1 - propose a name for every file, in processing order.
        // The sequence counter advances for every file regardless of the status
        // that file will end up with (rule 9), which falls out of using the
        // loop ordinal directly.
        var proposed = new string[ordered.Count];
        for (var i = 0; i < ordered.Count; i++)
        {
            proposed[i] = StepEngine.ApplyAll(ordered[i].Name, rules, i);
        }

        // Existing names in the folder, and how many items propose each name.
        var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var file in ordered)
        {
            existing.Add(file.Name);
        }

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var name in proposed)
        {
            proposedCounts[name] = proposedCounts.TryGetValue(name, out var n) ? n + 1 : 1;
        }

        // Pass 2 - classify, in the precedence order of rule 13.
        var items = new List<PlanItem>(ordered.Count);
        var summary = new PlanSummary { Total = ordered.Count };

        for (var i = 0; i < ordered.Count; i++)
        {
            var original = ordered[i].Name;
            var candidate = proposed[i];
            string status;
            string reason;

            if (!NameValidator.IsValid(candidate, out var invalidReason))
            {
                status = PlanStatus.Invalid;
                reason = invalidReason;
                summary.Invalid++;
            }
            else if (CollidesWithExistingFile(candidate, original, existing))
            {
                status = PlanStatus.Collision;
                reason = "target name already exists in the folder";
                summary.Collision++;
            }
            else if (proposedCounts[candidate] > 1)
            {
                status = PlanStatus.Collision;
                reason = "another file is proposed the same name";
                summary.Collision++;
            }
            else if (string.Equals(candidate, original, StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = "no change";
                summary.Unchanged++;
            }
            else
            {
                status = PlanStatus.Ok;
                reason = string.Empty;
                summary.Ok++;
            }

            items.Add(new PlanItem(original, candidate, status, reason));
        }

        return new RenamePlan(items, summary);
    }

    /// <summary>
    /// "equals (case-INsensitive) an existing file in the folder other than
    /// this item". The item's own original name is the one entry that does not
    /// count against it.
    /// </summary>
    private static bool CollidesWithExistingFile(string candidate, string original, HashSet<string> existing)
    {
        if (!existing.Contains(candidate))
        {
            return false;
        }

        return !string.Equals(candidate, original, StringComparison.OrdinalIgnoreCase);
    }
}

