using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Text.Unicode;

namespace BatchRenameStudio.Core;

/// <summary>Reader and writer for the <c>rules.json</c> contract.</summary>
public static class RuleSetJson
{
    private static readonly JsonDocumentOptions DocumentOptions = new()
    {
        AllowTrailingCommas = true,
        CommentHandling = JsonCommentHandling.Skip,
    };

    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            throw new RuleFormatException($"Cannot read rules file '{path}': {ex.Message}");
        }

        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument document;
        try
        {
            document = JsonDocument.Parse(json, DocumentOptions);
        }
        catch (JsonException ex)
        {
            throw new RuleFormatException($"rules.json is not valid JSON: {ex.Message}");
        }

        using (document)
        {
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RuleFormatException("rules.json must contain a JSON object at the root.");
            }

            var rules = new RuleSet
            {
                ApplyTo = ReadApplyTo(root),
                Sort = ReadSort(root),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RuleFormatException("\"steps\" must be an array.");
                }

                var index = 0;
                foreach (var element in steps.EnumerateArray())
                {
                    rules.Steps.Add(ReadStep(element, index));
                    index++;
                }
            }

            return rules;
        }
    }

    private static ApplyTo ReadApplyTo(JsonElement root)
    {
        var value = ReadString(root, "applyTo") ?? "name";
        return value.ToLowerInvariant() switch
        {
            "name" => ApplyTo.Name,
            "nameandextension" => ApplyTo.NameAndExtension,
            _ => throw new RuleFormatException($"Unknown applyTo value \"{value}\"."),
        };
    }

    private static SortMode ReadSort(JsonElement root)
    {
        var value = ReadString(root, "sort") ?? "name";
        return value.ToLowerInvariant() switch
        {
            "name" => SortMode.Name,
            "created" => SortMode.Created,
            "modified" => SortMode.Modified,
            _ => throw new RuleFormatException($"Unknown sort value \"{value}\"."),
        };
    }

    private static RuleStep ReadStep(JsonElement element, int index)
    {
        if (element.ValueKind != JsonValueKind.Object)
        {
            throw new RuleFormatException($"steps[{index}] must be an object.");
        }

        var opText = ReadString(element, "op")
                     ?? throw new RuleFormatException($"steps[{index}] is missing \"op\".");

        var step = new RuleStep
        {
            Op = opText.ToLowerInvariant() switch
            {
                "replace" => StepOp.Replace,
                "insert" => StepOp.Insert,
                "remove" => StepOp.Remove,
                "sequence" => StepOp.Sequence,
                "case" => StepOp.Case,
                "extension" => StepOp.Extension,
                _ => throw new RuleFormatException($"steps[{index}] has unknown op \"{opText}\"."),
            },
            Enabled = ReadBool(element, "enabled") ?? true,
        };

        switch (step.Op)
        {
            case StepOp.Replace:
                step.Find = ReadString(element, "find") ?? string.Empty;
                step.ReplaceWith = ReadString(element, "replaceWith") ?? string.Empty;
                step.Regex = ReadBool(element, "regex") ?? false;
                step.IgnoreCase = ReadBool(element, "ignoreCase") ?? false;
                if (step.Regex && step.Find.Length > 0)
                {
                    try
                    {
                        _ = new Regex(step.Find, RegexOptions.CultureInvariant);
                    }
                    catch (ArgumentException ex)
                    {
                        throw new RuleFormatException($"steps[{index}] has an invalid regex: {ex.Message}");
                    }
                }

                break;

            case StepOp.Insert:
                step.Text = ReadString(element, "text") ?? string.Empty;
                var insertPosition = ReadString(element, "position") ?? "prefix";
                step.InsertPosition = insertPosition.ToLowerInvariant() switch
                {
                    "prefix" => InsertPosition.Prefix,
                    "suffix" => InsertPosition.Suffix,
                    "index" => InsertPosition.Index,
                    _ => throw new RuleFormatException($"steps[{index}] has unknown position \"{insertPosition}\"."),
                };
                step.Index = ReadInt(element, "index") ?? 0;
                break;

            case StepOp.Remove:
                step.From = ReadInt(element, "from") ?? 0;
                step.Count = ReadInt(element, "count") ?? 0;
                break;

            case StepOp.Sequence:
                step.Pattern = ReadString(element, "pattern") ?? "{n:000}";
                step.Start = ReadInt(element, "start") ?? 1;
                step.Step = ReadInt(element, "step") ?? 1;
                var seqPosition = ReadString(element, "position") ?? "prefix";
                step.SequencePosition = seqPosition.ToLowerInvariant() switch
                {
                    "prefix" => SequencePosition.Prefix,
                    "suffix" => SequencePosition.Suffix,
                    _ => throw new RuleFormatException($"steps[{index}] has unknown position \"{seqPosition}\"."),
                };
                break;

            case StepOp.Case:
                var caseMode = ReadString(element, "mode")
                               ?? throw new RuleFormatException($"steps[{index}] is missing \"mode\".");
                step.CaseMode = caseMode.ToLowerInvariant() switch
                {
                    "upper" => CaseMode.Upper,
                    "lower" => CaseMode.Lower,
                    "title" => CaseMode.Title,
                    _ => throw new RuleFormatException($"steps[{index}] has unknown case mode \"{caseMode}\"."),
                };
                break;

            case StepOp.Extension:
                var extMode = ReadString(element, "mode")
                              ?? throw new RuleFormatException($"steps[{index}] is missing \"mode\".");
                step.ExtensionMode = extMode.ToLowerInvariant() switch
                {
                    "lower" => ExtensionMode.Lower,
                    "upper" => ExtensionMode.Upper,
                    "set" => ExtensionMode.Set,
                    _ => throw new RuleFormatException($"steps[{index}] has unknown extension mode \"{extMode}\"."),
                };
                step.Value = ReadString(element, "value") ?? string.Empty;
                break;
        }

        return step;
    }

    private static string? ReadString(JsonElement element, string name)
    {
        if (!element.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        if (value.ValueKind != JsonValueKind.String)
        {
            throw new RuleFormatException($"\"{name}\" must be a string.");
        }

        return value.GetString() ?? string.Empty;
    }

    private static bool? ReadBool(JsonElement element, string name)
    {
        if (!element.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => throw new RuleFormatException($"\"{name}\" must be true or false."),
        };
    }

    private static int? ReadInt(JsonElement element, string name)
    {
        if (!element.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return null;
        }

        if (value.ValueKind != JsonValueKind.Number || !value.TryGetInt32(out var number))
        {
            throw new RuleFormatException($"\"{name}\" must be a 32-bit integer.");
        }

        return number;
    }

    // ---- writing (used by the GUI's "Save rules" command) ----

    private static readonly JsonWriterOptions WriterOptions = new()
    {
        Indented = true,
        Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
    };

    public static string Serialize(RuleSet rules)
    {
        using var buffer = new MemoryStream();
        using (var writer = new Utf8JsonWriter(buffer, WriterOptions))
        {
            writer.WriteStartObject();
            writer.WriteString("applyTo", rules.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
            writer.WriteString("sort", rules.Sort.ToString().ToLowerInvariant());
            writer.WriteStartArray("steps");
            foreach (var step in rules.Steps)
            {
                WriteStep(writer, step);
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    public static void Save(string path, RuleSet rules) =>
        File.WriteAllBytes(path, Encoding.UTF8.GetBytes(Serialize(rules)));

    private static void WriteStep(Utf8JsonWriter writer, RuleStep step)
    {
        writer.WriteStartObject();
        writer.WriteString("op", step.Op.ToString().ToLowerInvariant());
        switch (step.Op)
        {
            case StepOp.Replace:
                writer.WriteString("find", step.Find);
                writer.WriteString("replaceWith", step.ReplaceWith);
                writer.WriteBoolean("regex", step.Regex);
                writer.WriteBoolean("ignoreCase", step.IgnoreCase);
                break;
            case StepOp.Insert:
                writer.WriteString("text", step.Text);
                writer.WriteString("position", step.InsertPosition.ToString().ToLowerInvariant());
                writer.WriteNumber("index", step.Index);
                break;
            case StepOp.Remove:
                writer.WriteNumber("from", step.From);
                writer.WriteNumber("count", step.Count);
                break;
            case StepOp.Sequence:
                writer.WriteString("pattern", step.Pattern);
                writer.WriteNumber("start", step.Start);
                writer.WriteNumber("step", step.Step);
                writer.WriteString("position", step.SequencePosition.ToString().ToLowerInvariant());
                break;
            case StepOp.Case:
                writer.WriteString("mode", step.CaseMode.ToString().ToLowerInvariant());
                break;
            case StepOp.Extension:
                writer.WriteString("mode", step.ExtensionMode.ToString().ToLowerInvariant());
                if (step.ExtensionMode == ExtensionMode.Set)
                {
                    writer.WriteString("value", step.Value);
                }

                break;
        }

        // Only written when it deviates from the contract default, so a rule set
        // built in the GUI stays readable by any consumer of the plain contract.
        if (!step.Enabled)
        {
            writer.WriteBoolean("enabled", false);
        }

        writer.WriteEndObject();
    }
}

