using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Unicode;

namespace BatchRenameStudio.Core;

/// <summary>
/// Writes <c>plan.json</c> exactly as the contract specifies: schemaVersion,
/// items in processing order, summary. The bytes are UTF-8 without a BOM and
/// depend only on the plan's content, so identical inputs give an identical
/// file (rule 15).
/// </summary>
public static class PlanJson
{
    private static readonly JsonWriterOptions WriterOptions = new()
    {
        Indented = true,
        // Non-ASCII file names stay readable; the HTML-sensitive ASCII set is
        // still escaped, which keeps the output safe to embed anywhere.
        Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
    };

    public static byte[] SerializeToUtf8(RenamePlan plan)
    {
        using var buffer = new MemoryStream();
        using (var writer = new Utf8JsonWriter(buffer, WriterOptions))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", plan.SchemaVersion);

            writer.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                writer.WriteStartObject();
                writer.WriteString("original", item.Original);
                writer.WriteString("proposed", item.Proposed);
                writer.WriteString("status", item.Status);
                writer.WriteString("reason", item.Reason);
                writer.WriteEndObject();
            }

            writer.WriteEndArray();

            writer.WriteStartObject("summary");
            writer.WriteNumber("total", plan.Summary.Total);
            writer.WriteNumber("ok", plan.Summary.Ok);
            writer.WriteNumber("collision", plan.Summary.Collision);
            writer.WriteNumber("unchanged", plan.Summary.Unchanged);
            writer.WriteNumber("invalid", plan.Summary.Invalid);
            writer.WriteEndObject();

            writer.WriteEndObject();
        }

        return buffer.ToArray();
    }

    /// <summary>Writes the plan as UTF-8 without a byte order mark.</summary>
    public static void Write(string path, RenamePlan plan)
    {
        var directory = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(directory))
        {
            Directory.CreateDirectory(directory);
        }

        // WriteAllBytes emits exactly these bytes - no encoding preamble.
        File.WriteAllBytes(path, SerializeToUtf8(plan));
    }
}

