namespace BatchRenameStudio.Core;

public sealed class RenameOperation
{
    public RenameOperation(string from, string to)
    {
        From = from;
        To = to;
    }

    public string From { get; }

    public string To { get; }
}

/// <summary>The record of one applied batch - the unit of undo.</summary>
public sealed class RenameBatch
{
    public RenameBatch(string directory, DateTime timestampUtc, IReadOnlyList<RenameOperation> operations)
    {
        Directory = directory;
        TimestampUtc = timestampUtc;
        Operations = operations;
    }

    public string Directory { get; }

    public DateTime TimestampUtc { get; }

    /// <summary>Renames that actually happened, in the order they happened.</summary>
    public IReadOnlyList<RenameOperation> Operations { get; }

    /// <summary>Set when the batch was restored from a journal file on disk.</summary>
    public string? JournalPath { get; set; }
}

public sealed class RenameFailure
{
    public RenameFailure(string name, string message)
    {
        Name = name;
        Message = message;
    }

    public string Name { get; }

    public string Message { get; }
}

public sealed class RenameResult
{
    public RenameResult(RenameBatch batch, IReadOnlyList<RenameFailure> failures)
    {
        Batch = batch;
        Failures = failures;
    }

    public RenameBatch Batch { get; }

    public IReadOnlyList<RenameFailure> Failures { get; }

    public int Renamed => Batch.Operations.Count;
}

/// <summary>Performs the renames of a plan and the reverse of a batch.</summary>
public static class RenameExecutor
{
    /// <summary>
    /// Renames every item whose status is "ok". Items of any other status are
    /// skipped - a plan guarantees that no "ok" target matches an existing file
    /// or another "ok" target, so a straight sequential pass is safe.
    /// </summary>
    public static RenameResult Apply(
        string directory,
        RenamePlan plan,
        IProgress<int>? progress = null,
        CancellationToken cancellationToken = default)
    {
        var done = new List<RenameOperation>();
        var failures = new List<RenameFailure>();
        var processed = 0;

        foreach (var item in plan.Items)
        {
            cancellationToken.ThrowIfCancellationRequested();
            processed++;
            progress?.Report(processed);

            if (!item.IsActionable)
            {
                continue;
            }

            var from = Path.Combine(directory, item.Original);
            var to = Path.Combine(directory, item.Proposed);
            try
            {
                MoveFile(from, to);
                done.Add(new RenameOperation(item.Original, item.Proposed));
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                failures.Add(new RenameFailure(item.Original, ex.Message));
            }
        }

        var batch = new RenameBatch(directory, DateTime.UtcNow, done);
        return new RenameResult(batch, failures);
    }

    /// <summary>Reverses a batch, newest operation first.</summary>
    public static IReadOnlyList<RenameFailure> Undo(RenameBatch batch)
    {
        var failures = new List<RenameFailure>();
        for (var i = batch.Operations.Count - 1; i >= 0; i--)
        {
            var op = batch.Operations[i];
            var current = Path.Combine(batch.Directory, op.To);
            var restored = Path.Combine(batch.Directory, op.From);
            try
            {
                if (!File.Exists(current))
                {
                    failures.Add(new RenameFailure(op.To, "file is no longer there"));
                    continue;
                }

                if (!SameFileIgnoringCase(op.To, op.From) && File.Exists(restored))
                {
                    failures.Add(new RenameFailure(op.To, $"\"{op.From}\" exists again - cannot restore"));
                    continue;
                }

                MoveFile(current, restored);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                failures.Add(new RenameFailure(op.To, ex.Message));
            }
        }

        return failures;
    }

    private static bool SameFileIgnoringCase(string a, string b) =>
        string.Equals(a, b, StringComparison.OrdinalIgnoreCase);

    /// <summary>
    /// File.Move, with a detour through a temporary name when only the casing
    /// changes - that keeps the rename working on any case-insensitive volume.
    /// </summary>
    private static void MoveFile(string from, string to)
    {
        var fromName = Path.GetFileName(from);
        var toName = Path.GetFileName(to);
        if (!string.Equals(fromName, toName, StringComparison.Ordinal) &&
            string.Equals(fromName, toName, StringComparison.OrdinalIgnoreCase))
        {
            var directory = Path.GetDirectoryName(from) ?? string.Empty;
            var temporary = Path.Combine(directory, "~brs-" + Guid.NewGuid().ToString("N") + ".tmp");
            File.Move(from, temporary);
            try
            {
                File.Move(temporary, to);
            }
            catch
            {
                // Never leave the file parked under the temporary name.
                File.Move(temporary, from);
                throw;
            }

            return;
        }

        File.Move(from, to);
    }
}

