using System.Globalization;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Unicode;

namespace BatchRenameStudio.Core;

/// <summary>
/// Persists every applied batch to disk so that an undo survives closing the
/// application. One JSON file per batch under
/// %LOCALAPPDATA%\BatchRenameStudio\journal.
/// </summary>
public static class UndoJournal
{
    private const int KeepNewest = 50;

    private static readonly JsonWriterOptions WriterOptions = new()
    {
        Indented = true,
        Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
    };

    public static string JournalDirectory =>
        Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "BatchRenameStudio",
            "journal");

    public static string? TrySave(RenameBatch batch)
    {
        if (batch.Operations.Count == 0)
        {
            return null;
        }

        try
        {
            Directory.CreateDirectory(JournalDirectory);
            var name = batch.TimestampUtc.ToString("yyyyMMdd'T'HHmmss'.'fff", CultureInfo.InvariantCulture) + ".json";
            var path = Path.Combine(JournalDirectory, name);

            using (var stream = File.Create(path))
            using (var writer = new Utf8JsonWriter(stream, WriterOptions))
            {
                writer.WriteStartObject();
                writer.WriteNumber("schemaVersion", 1);
                writer.WriteString("directory", batch.Directory);
                writer.WriteString("timestampUtc", batch.TimestampUtc.ToString("O", CultureInfo.InvariantCulture));
                writer.WriteStartArray("operations");
                foreach (var op in batch.Operations)
                {
                    writer.WriteStartObject();
                    writer.WriteString("from", op.From);
                    writer.WriteString("to", op.To);
                    writer.WriteEndObject();
                }

                writer.WriteEndArray();
                writer.WriteEndObject();
            }

            batch.JournalPath = path;
            Prune();
            return path;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            // The journal is a convenience; failing to write it must never
            // break a rename that already succeeded.
            return null;
        }
    }

    /// <summary>Loads saved batches, oldest first, so they can seed the undo stack.</summary>
    public static List<RenameBatch> LoadAll()
    {
        var batches = new List<RenameBatch>();
        if (!Directory.Exists(JournalDirectory))
        {
            return batches;
        }

        foreach (var path in Directory.GetFiles(JournalDirectory, "*.json").OrderBy(p => p, StringComparer.Ordinal))
        {
            var batch = TryLoad(path);
            if (batch != null)
            {
                batches.Add(batch);
            }
        }

        return batches;
    }

    public static void Discard(RenameBatch batch)
    {
        if (batch.JournalPath == null)
        {
            return;
        }

        try
        {
            File.Delete(batch.JournalPath);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            // Nothing useful to do - a stale journal entry is harmless.
        }

        batch.JournalPath = null;
    }

    private static RenameBatch? TryLoad(string path)
    {
        try
        {
            using var document = JsonDocument.Parse(File.ReadAllText(path));
            var root = document.RootElement;
            var directory = root.GetProperty("directory").GetString();
            if (string.IsNullOrEmpty(directory))
            {
                return null;
            }

            var timestamp = DateTime.TryParse(
                root.TryGetProperty("timestampUtc", out var ts) ? ts.GetString() : null,
                CultureInfo.InvariantCulture,
                DateTimeStyles.RoundtripKind,
                out var parsed)
                ? parsed
                : File.GetLastWriteTimeUtc(path);

            var operations = new List<RenameOperation>();
            if (root.TryGetProperty("operations", out var ops) && ops.ValueKind == JsonValueKind.Array)
            {
                foreach (var op in ops.EnumerateArray())
                {
                    var from = op.TryGetProperty("from", out var f) ? f.GetString() : null;
                    var to = op.TryGetProperty("to", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrEmpty(from) && !string.IsNullOrEmpty(to))
                    {
                        operations.Add(new RenameOperation(from, to));
                    }
                }
            }

            if (operations.Count == 0)
            {
                return null;
            }

            return new RenameBatch(directory, timestamp, operations) { JournalPath = path };
        }
        catch (Exception ex) when (ex is IOException or JsonException or KeyNotFoundException or InvalidOperationException)
        {
            return null;
        }
    }

    private static void Prune()
    {
        try
        {
            var files = Directory.GetFiles(JournalDirectory, "*.json")
                .OrderByDescending(p => p, StringComparer.Ordinal)
                .Skip(KeepNewest)
                .ToList();
            foreach (var file in files)
            {
                File.Delete(file);
            }
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            // Pruning is best effort.
        }
    }
}

