namespace BatchRenameStudio.Cli;

/// <summary>Minimal argument parser: <c>--key value</c> and <c>--key=value</c>.</summary>
public sealed class CommandLine
{
    private readonly Dictionary<string, string?> _options = new(StringComparer.OrdinalIgnoreCase);
    private readonly List<string> _positional = new();

    private CommandLine()
    {
    }

    public IReadOnlyList<string> Positional => _positional;

    public static CommandLine Parse(string[] args)
    {
        var result = new CommandLine();
        for (var i = 0; i < args.Length; i++)
        {
            var arg = args[i];
            if (!arg.StartsWith("--", StringComparison.Ordinal))
            {
                result._positional.Add(arg);
                continue;
            }

            var body = arg.Substring(2);
            var eq = body.IndexOf('=');
            if (eq >= 0)
            {
                result._options[body.Substring(0, eq)] = body.Substring(eq + 1);
                continue;
            }

            var hasValue = i + 1 < args.Length && !args[i + 1].StartsWith("--", StringComparison.Ordinal);
            result._options[body] = hasValue ? args[++i] : null;
        }

        return result;
    }

    public bool Has(string name) => _options.ContainsKey(name);

    public string? Value(string name) => _options.TryGetValue(name, out var value) ? value : null;

    /// <summary>
    /// True when the process was started for a console mode. Anything else
    /// starts the GUI.
    /// </summary>
    public static bool IsHeadless(string[] args)
    {
        foreach (var arg in args)
        {
            var name = arg.StartsWith("--", StringComparison.Ordinal) ? arg.Substring(2) : arg;
            var eq = name.IndexOf('=');
            if (eq >= 0)
            {
                name = name.Substring(0, eq);
            }

            switch (name.ToLowerInvariant())
            {
                case "plan":
                case "selftest":
                case "help":
                case "version":
                case "-h":
                case "h":
                case "?":
                    return true;
            }
        }

        return false;
    }
}

