using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// A WinExe has no console of its own. When the caller redirected stdout or
/// stderr the handles are inherited and Console already works; when it did not,
/// we attach to the parent console so that a human running the tool from a
/// prompt still sees the output.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;
    private const int AttachParentProcess = -1;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int processId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int handle);

    public static void Ensure()
    {
        var needsConsole = !IsValid(GetStdHandle(StdOutputHandle)) || !IsValid(GetStdHandle(StdErrorHandle));
        if (!needsConsole)
        {
            // Redirected to a pipe or file: leave the streams exactly as they are.
            return;
        }

        if (!AttachConsole(AttachParentProcess))
        {
            return;
        }

        Reopen("CONOUT$", StdOutputHandle);
        Reopen("CONOUT$", StdErrorHandle);
    }

    private static bool IsValid(IntPtr handle) => handle != IntPtr.Zero && handle != new IntPtr(-1);

    private static void Reopen(string device, int stdHandle)
    {
        if (IsValid(GetStdHandle(stdHandle)))
        {
            return;
        }

        try
        {
            var stream = new FileStream(device, FileMode.Open, FileAccess.Write);
            var writer = new StreamWriter(stream, new UTF8Encoding(false)) { AutoFlush = true };
            if (stdHandle == StdOutputHandle)
            {
                Console.SetOut(writer);
            }
            else
            {
                Console.SetError(writer);
            }
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or ArgumentException)
        {
            // Without a console there is nowhere to report this; the exit code
            // still carries the outcome.
        }
    }
}

