using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>Exit codes of the headless modes.</summary>
internal static class ExitCode
{
    public const int Success = 0;
    public const int UsageError = 2;
    public const int InputError = 3;
    public const int Failure = 4;
}

internal static class CliRunner
{
    public static int Run(string[] args)
    {
        var command = CommandLine.Parse(args);

        if (command.Has("help") || command.Has("?"))
        {
            PrintUsage();
            return ExitCode.Success;
        }

        if (command.Has("version"))
        {
            Console.WriteLine("BatchRenameStudio 1.0");
            return ExitCode.Success;
        }

        if (command.Has("selftest"))
        {
            return SelfTest.Run();
        }

        if (command.Has("plan"))
        {
            return RunPlan(command);
        }

        PrintUsage();
        return ExitCode.UsageError;
    }

    private static int RunPlan(CommandLine command)
    {
        var directory = command.Value("dir");
        var rulesPath = command.Value("rules");
        var outPath = command.Value("out");

        if (string.IsNullOrWhiteSpace(directory) ||
            string.IsNullOrWhiteSpace(rulesPath) ||
            string.IsNullOrWhiteSpace(outPath))
        {
            Console.Error.WriteLine("usage: BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
            return ExitCode.UsageError;
        }

        RuleSet rules;
        try
        {
            rules = RuleSetJson.Load(rulesPath);
        }
        catch (RuleFormatException ex)
        {
            Console.Error.WriteLine(ex.Message);
            return ExitCode.InputError;
        }
        catch (FileNotFoundException)
        {
            Console.Error.WriteLine($"Rules file not found: {rulesPath}");
            return ExitCode.InputError;
        }
        catch (DirectoryNotFoundException)
        {
            Console.Error.WriteLine($"Rules file not found: {rulesPath}");
            return ExitCode.InputError;
        }

        RenamePlan plan;
        try
        {
            // --plan only reads the folder. Nothing here renames anything.
            plan = PlanBuilder.Build(directory, rules);
        }
        catch (DirectoryNotFoundException ex)
        {
            Console.Error.WriteLine(ex.Message);
            return ExitCode.InputError;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"Cannot read folder '{directory}': {ex.Message}");
            return ExitCode.Failure;
        }

        try
        {
            PlanJson.Write(outPath, plan);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine($"Cannot write plan '{outPath}': {ex.Message}");
            return ExitCode.Failure;
        }

        // The one and only line this mode prints to stdout.
        Console.Out.WriteLine(plan.Summary.ToString());
        Console.Out.Flush();
        return ExitCode.Success;
    }

    private static void PrintUsage()
    {
        Console.WriteLine("Batch Rename Studio");
        Console.WriteLine();
        Console.WriteLine("  BatchRenameStudio.exe");
        Console.WriteLine("      Start the graphical rename workbench.");
        Console.WriteLine();
        Console.WriteLine("  BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
        Console.WriteLine("      Compute a rename plan and write it as JSON. Renames nothing.");
        Console.WriteLine();
        Console.WriteLine("  BatchRenameStudio.exe --selftest");
        Console.WriteLine("      Run the built-in contract tests against a temporary folder.");
    }
}

