using System.Text;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Built-in contract tests. The stack allows no external test packages, so the
/// checks ship inside the executable and run with <c>--selftest</c>. Each case
/// creates a throw-away folder, builds a plan and compares it to the expected
/// (proposed, status) pairs.
/// </summary>
internal static class SelfTest
{
    private static int _passed;
    private static readonly List<string> Failures = new();

    public static int Run()
    {
        var root = Path.Combine(Path.GetTempPath(), "brs-selftest-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(root);
        try
        {
            NameSplitCases();
            StepCases();
            SequenceCases();
            StatusCases(root);
            SortCases(root);
            OutputCases(root);
        }
        finally
        {
            TryDeleteTree(root);
        }

        Console.WriteLine();
        Console.WriteLine($"{_passed} passed, {Failures.Count} failed");
        foreach (var failure in Failures)
        {
            Console.WriteLine("  FAIL " + failure);
        }

        return Failures.Count == 0 ? ExitCode.Success : ExitCode.Failure;
    }

    // ---- rule 2: the name split ----

    private static void NameSplitCases()
    {
        Section("name split");
        CheckSplit("a.txt", "a", "txt");
        CheckSplit("archive.tar.gz", "archive.tar", "gz");
        CheckSplit(".gitignore", ".gitignore", string.Empty);
        CheckSplit("README", "README", string.Empty);
        CheckSplit("trailing.", "trailing", string.Empty);
        CheckSplit(".", ".", string.Empty);
    }

    private static void CheckSplit(string name, string expectedBase, string expectedExt)
    {
        var parts = NameParts.Split(name);
        Check(
            parts.Base == expectedBase && parts.Extension == expectedExt,
            $"split(\"{name}\") = (\"{parts.Base}\",\"{parts.Extension}\"), expected (\"{expectedBase}\",\"{expectedExt}\")");
    }

    // ---- rules 3, 6-12: the individual operations ----

    private static void StepCases()
    {
        Section("steps");

        Expect(
            "replace literal, all occurrences",
            new[] { "a-a-a.txt" },
            """{"steps":[{"op":"replace","find":"a","replaceWith":"b"}]}""",
            ("a-a-a.txt", "b-b-b.txt", PlanStatus.Ok));

        Expect(
            "replace is case sensitive by default",
            new[] { "Aa.txt" },
            """{"steps":[{"op":"replace","find":"a","replaceWith":"z"}]}""",
            ("Aa.txt", "Az.txt", PlanStatus.Ok));

        Expect(
            "replace ignoreCase, literal",
            new[] { "Aa.txt" },
            """{"steps":[{"op":"replace","find":"a","replaceWith":"z","ignoreCase":true}]}""",
            ("Aa.txt", "zz.txt", PlanStatus.Ok));

        Expect(
            "replace regex with group reference",
            new[] { "IMG_0042.JPG" },
            """{"steps":[{"op":"replace","find":"IMG_(\\d+)","replaceWith":"photo-$1","regex":true}]}""",
            ("IMG_0042.JPG", "photo-0042.JPG", PlanStatus.Ok));

        Expect(
            "replace regex, ignoreCase",
            new[] { "img_7.png" },
            """{"steps":[{"op":"replace","find":"IMG_(\\d+)","replaceWith":"P$1","regex":true,"ignoreCase":true}]}""",
            ("img_7.png", "P7.png", PlanStatus.Ok));

        Expect(
            "replace only touches the base under applyTo name",
            new[] { "txt.txt" },
            """{"steps":[{"op":"replace","find":"txt","replaceWith":"doc"}]}""",
            ("txt.txt", "doc.txt", PlanStatus.Ok));

        Expect(
            "replace touches the whole name under nameAndExtension",
            new[] { "txt.txt" },
            """{"applyTo":"nameAndExtension","steps":[{"op":"replace","find":"txt","replaceWith":"doc"}]}""",
            ("txt.txt", "doc.doc", PlanStatus.Ok));

        Expect(
            "insert prefix and suffix",
            new[] { "a.txt" },
            """{"steps":[{"op":"insert","text":"pre-","position":"prefix"},{"op":"insert","text":"-post","position":"suffix"}]}""",
            ("a.txt", "pre-a-post.txt", PlanStatus.Ok));

        Expect(
            "insert at index, clamped high",
            new[] { "ab.txt" },
            """{"steps":[{"op":"insert","text":"-","position":"index","index":99}]}""",
            ("ab.txt", "ab-.txt", PlanStatus.Ok));

        Expect(
            "insert at index, clamped low",
            new[] { "ab.txt" },
            """{"steps":[{"op":"insert","text":"-","position":"index","index":-5}]}""",
            ("ab.txt", "-ab.txt", PlanStatus.Ok));

        Expect(
            "remove range",
            new[] { "abcdef.txt" },
            """{"steps":[{"op":"remove","from":1,"count":3}]}""",
            ("abcdef.txt", "aef.txt", PlanStatus.Ok));

        Expect(
            "remove clamps count to what remains",
            new[] { "abc.txt" },
            """{"steps":[{"op":"remove","from":2,"count":99}]}""",
            ("abc.txt", "ab.txt", PlanStatus.Ok));

        Expect(
            "remove past the end is a no-op",
            new[] { "abc.txt" },
            """{"steps":[{"op":"remove","from":9,"count":3}]}""",
            ("abc.txt", "abc.txt", PlanStatus.Unchanged));

        Expect(
            "case upper and lower",
            new[] { "MiXeD.TxT" },
            """{"steps":[{"op":"case","mode":"lower"}]}""",
            ("MiXeD.TxT", "mixed.TxT", PlanStatus.Ok));

        Expect(
            "case title over letter runs",
            new[] { "hello wORLD-foo7bar.txt" },
            """{"steps":[{"op":"case","mode":"title"}]}""",
            ("hello wORLD-foo7bar.txt", "Hello World-Foo7Bar.txt", PlanStatus.Ok));

        Expect(
            "case upper under nameAndExtension covers the extension",
            new[] { "a.txt" },
            """{"applyTo":"nameAndExtension","steps":[{"op":"case","mode":"upper"}]}""",
            ("a.txt", "A.TXT", PlanStatus.Ok));

        Expect(
            "extension lower ignores applyTo name",
            new[] { "Doc.TXT" },
            """{"steps":[{"op":"extension","mode":"lower"}]}""",
            ("Doc.TXT", "Doc.txt", PlanStatus.Ok));

        Expect(
            "extension set adds one to a file without an extension",
            new[] { "README" },
            """{"steps":[{"op":"extension","mode":"set","value":"md"}]}""",
            ("README", "README.md", PlanStatus.Ok));

        Expect(
            "extension step applies to the trailing extension under nameAndExtension",
            new[] { "report.TXT" },
            """{"applyTo":"nameAndExtension","steps":[{"op":"case","mode":"upper"},{"op":"extension","mode":"lower"}]}""",
            ("report.TXT", "REPORT.txt", PlanStatus.Ok));

        Expect(
            "dotfile keeps its whole name as the base",
            new[] { ".gitignore" },
            """{"steps":[{"op":"insert","text":"x","position":"prefix"}]}""",
            (".gitignore", "x.gitignore", PlanStatus.Ok));

        Expect(
            "steps apply in array order",
            new[] { "a.txt" },
            """{"steps":[{"op":"insert","text":"1","position":"suffix"},{"op":"insert","text":"2","position":"suffix"}]}""",
            ("a.txt", "a12.txt", PlanStatus.Ok));
    }

    // ---- rule 9: the sequence counter ----

    private static void SequenceCases()
    {
        Section("sequence");

        Expect(
            "sequence numbers files in processing order",
            new[] { "b.txt", "a.txt", "c.txt" },
            """{"steps":[{"op":"sequence","pattern":"{n:000}_","start":1,"step":1,"position":"prefix"}]}""",
            ("a.txt", "001_a.txt", PlanStatus.Ok),
            ("b.txt", "002_b.txt", PlanStatus.Ok),
            ("c.txt", "003_c.txt", PlanStatus.Ok));

        Expect(
            "sequence honours start and step and suffix placement",
            new[] { "keep.txt", "x.txt" },
            """{"steps":[{"op":"sequence","pattern":"-{n:00}","start":5,"step":2,"position":"suffix"}]}""",
            ("keep.txt", "keep-05.txt", PlanStatus.Ok),
            ("x.txt", "x-07.txt", PlanStatus.Ok));

        Expect(
            "the counter advances past files that end up invalid",
            new[] { "a.txt", "b.txt", "c.txt" },
            """{"steps":[{"op":"replace","find":"b","replaceWith":"?"},{"op":"sequence","pattern":"{n:0}_","start":1,"step":1,"position":"prefix"}]}""",
            ("a.txt", "1_a.txt", PlanStatus.Ok),
            ("b.txt", "2_?.txt", PlanStatus.Invalid),
            ("c.txt", "3_c.txt", PlanStatus.Ok));

        Expect(
            "ordinal sort puts uppercase before lowercase",
            new[] { "a.txt", "B.txt" },
            """{"steps":[{"op":"sequence","pattern":"{n:0}-","start":1,"step":1,"position":"prefix"}]}""",
            ("B.txt", "1-B.txt", PlanStatus.Ok),
            ("a.txt", "2-a.txt", PlanStatus.Ok));

        Expect(
            "a pattern without a token is literal",
            new[] { "a.txt" },
            """{"steps":[{"op":"sequence","pattern":"n_","start":1,"step":1,"position":"prefix"}]}""",
            ("a.txt", "n_a.txt", PlanStatus.Ok));
    }

    // ---- rule 13: status precedence ----

    private static void StatusCases(string root)
    {
        Section("status");

        Expect(
            "no steps means unchanged",
            new[] { "a.txt" },
            """{"steps":[]}""",
            ("a.txt", "a.txt", PlanStatus.Unchanged));

        Expect(
            "collision against a file already in the folder",
            new[] { "a.txt", "b.txt" },
            """{"steps":[{"op":"replace","find":"a","replaceWith":"b"}]}""",
            ("a.txt", "b.txt", PlanStatus.Collision),
            ("b.txt", "b.txt", PlanStatus.Collision));

        Expect(
            "collision between two proposed names",
            new[] { "x1.txt", "x2.txt" },
            """{"steps":[{"op":"remove","from":1,"count":1}]}""",
            ("x1.txt", "x.txt", PlanStatus.Collision),
            ("x2.txt", "x.txt", PlanStatus.Collision));

        Expect(
            "collision is case insensitive",
            new[] { "a.txt", "z.txt" },
            """{"steps":[{"op":"replace","find":"z","replaceWith":"A"}]}""",
            ("a.txt", "a.txt", PlanStatus.Unchanged),
            ("z.txt", "A.txt", PlanStatus.Collision));

        Expect(
            "changing only the casing of a file is not a collision with itself",
            new[] { "a.txt" },
            """{"steps":[{"op":"case","mode":"upper"}]}""",
            ("a.txt", "A.txt", PlanStatus.Ok));

        Expect(
            "invalid beats collision",
            new[] { "a.txt", "b.txt" },
            """{"steps":[{"op":"insert","text":"?","position":"prefix"}]}""",
            ("a.txt", "?a.txt", PlanStatus.Invalid),
            ("b.txt", "?b.txt", PlanStatus.Invalid));

        Expect(
            "reserved device name",
            new[] { "x.txt" },
            """{"steps":[{"op":"replace","find":"x","replaceWith":"con"}]}""",
            ("x.txt", "con.txt", PlanStatus.Invalid));

        Expect(
            "reserved device name without an extension",
            new[] { "x" },
            """{"steps":[{"op":"replace","find":"x","replaceWith":"LPT9"}]}""",
            ("x", "LPT9", PlanStatus.Invalid));

        Expect(
            "COM10 is not reserved",
            new[] { "x.txt" },
            """{"steps":[{"op":"replace","find":"x","replaceWith":"COM10"}]}""",
            ("x.txt", "COM10.txt", PlanStatus.Ok));

        Expect(
            "empty proposed name is invalid",
            new[] { "ab" },
            """{"steps":[{"op":"remove","from":0,"count":10}]}""",
            ("ab", string.Empty, PlanStatus.Invalid));

        Expect(
            "every forbidden character is rejected",
            new[] { "a.txt" },
            """{"steps":[{"op":"insert","text":"<",  "position":"suffix"}]}""",
            ("a.txt", "a<.txt", PlanStatus.Invalid));

        Expect(
            "a name of 256 characters is invalid",
            new[] { "a.txt" },
            "{\"steps\":[{\"op\":\"insert\",\"text\":\"" + new string('x', 252) + "\",\"position\":\"suffix\"}]}",
            ("a.txt", "a" + new string('x', 252) + ".txt", PlanStatus.Invalid));

        Expect(
            "a name of exactly 255 characters is fine",
            new[] { "a.txt" },
            "{\"steps\":[{\"op\":\"insert\",\"text\":\"" + new string('x', 251) + "\",\"position\":\"suffix\"}]}",
            ("a.txt", "a" + new string('x', 251) + ".txt", PlanStatus.Ok));

        // Rule 1: directories are excluded entirely.
        var withFolder = NewFolder(root, "dirs");
        File.WriteAllText(Path.Combine(withFolder, "a.txt"), string.Empty);
        Directory.CreateDirectory(Path.Combine(withFolder, "b.txt"));
        Directory.CreateDirectory(Path.Combine(withFolder, "sub"));
        File.WriteAllText(Path.Combine(withFolder, "sub", "deep.txt"), string.Empty);
        var dirPlan = PlanBuilder.Build(withFolder, RuleSetJson.Parse("""{"steps":[]}"""));
        Check(dirPlan.Items.Count == 1 && dirPlan.Items[0].Original == "a.txt",
            "only files directly inside the folder are planned");
        Check(dirPlan.Summary.Total == 1 && dirPlan.Summary.Unchanged == 1, "summary counts only files");
    }

    // ---- rule 5: processing order from the file system ----

    private static void SortCases(string root)
    {
        Section("sort");

        var folder = NewFolder(root, "sort");
        var baseTime = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        var names = new[] { "a.txt", "b.txt", "c.txt" };
        // Creation order a, b, c but modification order c, b, a.
        for (var i = 0; i < names.Length; i++)
        {
            var path = Path.Combine(folder, names[i]);
            File.WriteAllText(path, string.Empty);
            File.SetCreationTimeUtc(path, baseTime.AddHours(i));
            File.SetLastWriteTimeUtc(path, baseTime.AddHours(10 - i));
        }

        var sequence = """{"sort":"%SORT%","steps":[{"op":"sequence","pattern":"{n:0}_","start":1,"step":1,"position":"prefix"}]}""";

        var created = PlanBuilder.Build(folder, RuleSetJson.Parse(sequence.Replace("%SORT%", "created")));
        Check(
            created.Items.Select(i => i.Proposed).SequenceEqual(new[] { "1_a.txt", "2_b.txt", "3_c.txt" }),
            "sort=created orders by creation time ascending");

        var modified = PlanBuilder.Build(folder, RuleSetJson.Parse(sequence.Replace("%SORT%", "modified")));
        Check(
            modified.Items.Select(i => i.Proposed).SequenceEqual(new[] { "1_c.txt", "2_b.txt", "3_a.txt" }),
            "sort=modified orders by modification time ascending");
        Check(
            modified.Items.Select(i => i.Original).SequenceEqual(new[] { "c.txt", "b.txt", "a.txt" }),
            "items are listed in processing order");
    }

    // ---- rules 14-15 and the output contract ----

    private static void OutputCases(string root)
    {
        Section("output");

        var folder = NewFolder(root, "output");
        foreach (var name in new[] { "a.txt", "b.txt", "中文.txt" })
        {
            File.WriteAllText(Path.Combine(folder, name), string.Empty);
        }

        var rules = RuleSetJson.Parse(
            """{"steps":[{"op":"sequence","pattern":"{n:000}_","start":1,"step":1,"position":"prefix"}]}""");

        var first = PlanJson.SerializeToUtf8(PlanBuilder.Build(folder, rules));
        var second = PlanJson.SerializeToUtf8(PlanBuilder.Build(folder, rules));
        Check(first.AsSpan().SequenceEqual(second), "the same inputs produce byte-identical output");

        Check(
            !(first.Length >= 3 && first[0] == 0xEF && first[1] == 0xBB && first[2] == 0xBF),
            "plan.json has no byte order mark");

        var text = Encoding.UTF8.GetString(first);
        Check(text.Contains("\"schemaVersion\": 1"), "schemaVersion is present");
        Check(text.Contains("\"summary\""), "summary is present");
        Check(text.Contains("\"total\": 3"), "summary counts all three files");

        var outPath = Path.Combine(folder, "..", "plan.json");
        PlanJson.Write(outPath, PlanBuilder.Build(folder, rules));
        var onDisk = File.ReadAllBytes(outPath);
        Check(onDisk.AsSpan().SequenceEqual(first), "the file on disk matches the serialized bytes");

        var namesAfter = Directory.GetFiles(folder).Select(Path.GetFileName).OrderBy(n => n, StringComparer.Ordinal);
        Check(
            namesAfter.SequenceEqual(new[] { "a.txt", "b.txt", "中文.txt" }.OrderBy(n => n, StringComparer.Ordinal)),
            "building a plan renames nothing");
    }

    // ---- harness ----

    private static void Expect(
        string title,
        string[] files,
        string rulesJson,
        params (string Original, string Proposed, string Status)[] expected)
    {
        var folder = Path.Combine(Path.GetTempPath(), "brs-case-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(folder);
        try
        {
            foreach (var name in files)
            {
                File.WriteAllText(Path.Combine(folder, name), "x");
            }

            var plan = PlanBuilder.Build(folder, RuleSetJson.Parse(rulesJson));
            if (plan.Items.Count != expected.Length)
            {
                Fail($"{title}: expected {expected.Length} items, got {plan.Items.Count}");
                return;
            }

            for (var i = 0; i < expected.Length; i++)
            {
                var actual = plan.Items[i];
                var want = expected[i];
                if (actual.Original != want.Original || actual.Proposed != want.Proposed || actual.Status != want.Status)
                {
                    Fail($"{title}: item {i} was (\"{actual.Original}\" -> \"{actual.Proposed}\", {actual.Status}), " +
                         $"expected (\"{want.Original}\" -> \"{want.Proposed}\", {want.Status})");
                    return;
                }
            }

            var counted = plan.Summary.Ok + plan.Summary.Collision + plan.Summary.Unchanged + plan.Summary.Invalid;
            if (counted != plan.Summary.Total || plan.Summary.Total != plan.Items.Count)
            {
                Fail($"{title}: summary does not add up ({plan.Summary})");
                return;
            }

            Pass(title);
        }
        catch (Exception ex)
        {
            Fail($"{title}: threw {ex.GetType().Name}: {ex.Message}");
        }
        finally
        {
            TryDeleteTree(folder);
        }
    }

    private static string NewFolder(string root, string name)
    {
        var path = Path.Combine(root, name);
        Directory.CreateDirectory(path);
        return path;
    }

    private static void Section(string name) => Console.WriteLine($"[{name}]");

    private static void Check(bool condition, string message)
    {
        if (condition)
        {
            Pass(message);
        }
        else
        {
            Fail(message);
        }
    }

    private static void Pass(string message)
    {
        _passed++;
        Console.WriteLine("  ok   " + message);
    }

    private static void Fail(string message)
    {
        Failures.Add(message);
        Console.WriteLine("  FAIL " + message);
    }

    private static void TryDeleteTree(string path)
    {
        try
        {
            if (Directory.Exists(path))
            {
                Directory.Delete(path, recursive: true);
            }
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            // Temporary folders that survive are the operating system's problem.
        }
    }
}

