using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Edits one <see cref="RuleStep"/>. The control set is rebuilt whenever a
/// different step is loaded, so each operation shows exactly its own fields and
/// nothing else. Every edit writes straight back into the step and raises
/// <see cref="Changed"/>, which drives the live preview.
/// </summary>
internal sealed class StepEditor : UserControl
{
    private readonly Label _title = new()
    {
        Dock = DockStyle.Top,
        Height = 28,
        TextAlign = ContentAlignment.MiddleLeft,
        Padding = new Padding(8, 0, 0, 0),
        Font = new Font(SystemFonts.MessageBoxFont!, FontStyle.Bold),
    };

    private readonly TableLayoutPanel _fields = new()
    {
        Dock = DockStyle.Fill,
        ColumnCount = 2,
        AutoScroll = true,
        Padding = new Padding(8),
    };

    private RuleStep? _step;
    private bool _loading;

    public StepEditor()
    {
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 110));
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        Controls.Add(_fields);
        Controls.Add(_title);
        ShowPlaceholder();
    }

    public event EventHandler? Changed;

    public void Load(RuleStep? step)
    {
        _step = step;
        _loading = true;
        _fields.SuspendLayout();
        foreach (Control control in _fields.Controls)
        {
            control.Dispose();
        }

        _fields.Controls.Clear();
        _fields.RowStyles.Clear();
        _fields.RowCount = 0;

        if (step == null)
        {
            ShowPlaceholder();
        }
        else
        {
            _title.Text = "  " + StepCatalog.DisplayName(step.Op);
            BuildFields(step);
        }

        _fields.ResumeLayout();
        _loading = false;
    }

    private void ShowPlaceholder()
    {
        _title.Text = "  No step selected";
        AddRow(string.Empty, new Label
        {
            Text = "Add a step on the left, then edit it here.",
            AutoSize = true,
            ForeColor = SystemColors.GrayText,
            Margin = new Padding(3, 6, 3, 3),
        });
    }

    private void BuildFields(RuleStep step)
    {
        switch (step.Op)
        {
            case StepOp.Replace:
                AddRow("Find", Text(step.Find, v => step.Find = v));
                AddRow("Replace with", Text(step.ReplaceWith, v => step.ReplaceWith = v));
                AddRow(string.Empty, Check("Regular expression ($1 refers to a group)", step.Regex, v => step.Regex = v));
                AddRow(string.Empty, Check("Ignore case", step.IgnoreCase, v => step.IgnoreCase = v));
                break;

            case StepOp.Insert:
                AddRow("Text", Text(step.Text, v => step.Text = v));
                var indexBox = Number(step.Index, 0, 100000, v => step.Index = v);
                indexBox.Enabled = step.InsertPosition == InsertPosition.Index;
                AddRow("Where", Choice(
                    new[] { "At the start", "At the end", "At index" },
                    (int)step.InsertPosition,
                    v =>
                    {
                        step.InsertPosition = (InsertPosition)v;
                        indexBox.Enabled = step.InsertPosition == InsertPosition.Index;
                    }));
                AddRow("Index", indexBox);
                break;

            case StepOp.Remove:
                AddRow("From index", Number(step.From, 0, 100000, v => step.From = v));
                AddRow("Characters", Number(step.Count, 0, 100000, v => step.Count = v));
                break;

            case StepOp.Sequence:
                AddRow("Pattern", Text(step.Pattern, v => step.Pattern = v));
                AddRow(string.Empty, Hint("{n:000} is the counter, zero padded to the width of the zeros."));
                AddRow("Start", Number(step.Start, -100000, 100000, v => step.Start = v));
                AddRow("Step", Number(step.Step, -100000, 100000, v => step.Step = v));
                AddRow("Where", Choice(
                    new[] { "At the start", "At the end" },
                    (int)step.SequencePosition,
                    v => step.SequencePosition = (SequencePosition)v));
                break;

            case StepOp.Case:
                AddRow("Mode", Choice(
                    new[] { "UPPERCASE", "lowercase", "Title Case" },
                    (int)step.CaseMode,
                    v => step.CaseMode = (CaseMode)v));
                break;

            case StepOp.Extension:
                var valueBox = Text(step.Value, v => step.Value = v);
                valueBox.Enabled = step.ExtensionMode == ExtensionMode.Set;
                AddRow("Mode", Choice(
                    new[] { "lowercase", "UPPERCASE", "Set to" },
                    (int)step.ExtensionMode,
                    v =>
                    {
                        step.ExtensionMode = (ExtensionMode)v;
                        valueBox.Enabled = step.ExtensionMode == ExtensionMode.Set;
                    }));
                AddRow("New extension", valueBox);
                AddRow(string.Empty, Hint("Without a leading dot. This step always targets the extension."));
                break;
        }
    }

    private void AddRow(string label, Control control)
    {
        var row = _fields.RowCount;
        _fields.RowCount = row + 1;
        _fields.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        _fields.Controls.Add(
            new Label
            {
                Text = label,
                AutoSize = true,
                Anchor = AnchorStyles.Left,
                Margin = new Padding(3, 7, 3, 3),
            },
            0,
            row);
        control.Anchor = AnchorStyles.Left | AnchorStyles.Right;
        _fields.Controls.Add(control, 1, row);
    }

    private static Label Hint(string text) => new()
    {
        Text = text,
        AutoSize = true,
        ForeColor = SystemColors.GrayText,
        Margin = new Padding(3, 0, 3, 6),
    };

    private TextBox Text(string value, Action<string> setter)
    {
        var box = new TextBox { Text = value };
        box.TextChanged += (_, _) =>
        {
            if (_loading)
            {
                return;
            }

            setter(box.Text);
            RaiseChanged();
        };
        return box;
    }

    private CheckBox Check(string caption, bool value, Action<bool> setter)
    {
        var box = new CheckBox { Text = caption, Checked = value, AutoSize = true };
        box.CheckedChanged += (_, _) =>
        {
            if (_loading)
            {
                return;
            }

            setter(box.Checked);
            RaiseChanged();
        };
        return box;
    }

    private NumericUpDown Number(int value, int min, int max, Action<int> setter)
    {
        var box = new NumericUpDown
        {
            Minimum = min,
            Maximum = max,
            Value = Math.Clamp(value, min, max),
            Width = 90,
        };
        box.ValueChanged += (_, _) =>
        {
            if (_loading)
            {
                return;
            }

            setter((int)box.Value);
            RaiseChanged();
        };
        return box;
    }

    private ComboBox Choice(string[] items, int selected, Action<int> setter)
    {
        var box = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList };
        box.Items.AddRange(items);
        box.SelectedIndex = Math.Clamp(selected, 0, items.Length - 1);
        box.SelectedIndexChanged += (_, _) =>
        {
            if (_loading)
            {
                return;
            }

            setter(box.SelectedIndex);
            RaiseChanged();
        };
        return box;
    }

    private void RaiseChanged() => Changed?.Invoke(this, EventArgs.Empty);
}

/// <summary>Display names and factory defaults for the six operations.</summary>
internal static class StepCatalog
{
    public static readonly StepOp[] All =
    {
        StepOp.Replace, StepOp.Insert, StepOp.Remove, StepOp.Sequence, StepOp.Case, StepOp.Extension,
    };

    public static string DisplayName(StepOp op) => op switch
    {
        StepOp.Replace => "Find and replace",
        StepOp.Insert => "Insert text",
        StepOp.Remove => "Remove characters",
        StepOp.Sequence => "Numbering",
        StepOp.Case => "Change case",
        StepOp.Extension => "Extension",
        _ => op.ToString(),
    };

    public static RuleStep Create(StepOp op) => op switch
    {
        StepOp.Replace => new RuleStep { Op = op },
        StepOp.Insert => new RuleStep { Op = op, Text = "new-", InsertPosition = InsertPosition.Prefix },
        StepOp.Remove => new RuleStep { Op = op, From = 0, Count = 1 },
        StepOp.Sequence => new RuleStep { Op = op, Pattern = "{n:000}_", Start = 1, Step = 1 },
        StepOp.Case => new RuleStep { Op = op, CaseMode = CaseMode.Lower },
        StepOp.Extension => new RuleStep { Op = op, ExtensionMode = ExtensionMode.Lower },
        _ => new RuleStep { Op = op },
    };
}

