using System.Diagnostics;
using System.Text;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The rename workbench: pick a folder, stack up rule steps, watch the preview
/// update as you edit, then apply - or undo the last batch.
/// </summary>
internal sealed class MainForm : Form
{
    private enum PreviewFilter
    {
        All,
        ChangesOnly,
        ProblemsOnly,
    }

    private readonly RuleSet _rules = new();
    private readonly List<FileEntry> _scan = new();
    private readonly List<int> _visible = new();
    private readonly Stack<RenameBatch> _undo = new();
    private readonly System.Windows.Forms.Timer _debounce = new() { Interval = 150 };

    private RenamePlan? _plan;
    private string? _folder;
    private bool _suppressStepEvents;

    private readonly ToolStripTextBox _folderBox = new() { Width = 380, ReadOnly = true };
    private readonly ToolStripComboBox _applyToBox = new() { Width = 150, DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly ToolStripComboBox _sortBox = new() { Width = 120, DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly ToolStripComboBox _filterBox = new() { Width = 150, DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly ToolStripButton _applyButton = new("Apply rename") { DisplayStyle = ToolStripItemDisplayStyle.Text };
    private readonly ToolStripButton _undoButton = new("Undo last batch") { DisplayStyle = ToolStripItemDisplayStyle.Text };

    private readonly ListView _stepList = new()
    {
        Dock = DockStyle.Fill,
        View = View.Details,
        CheckBoxes = true,
        FullRowSelect = true,
        HideSelection = false,
        MultiSelect = false,
        HeaderStyle = ColumnHeaderStyle.Nonclickable,
    };

    private readonly StepEditor _stepEditor = new() { Dock = DockStyle.Fill };

    private readonly ListView _preview = new()
    {
        Dock = DockStyle.Fill,
        View = View.Details,
        FullRowSelect = true,
        GridLines = true,
        VirtualMode = true,
        HideSelection = false,
    };

    private readonly ToolStripStatusLabel _summaryLabel = new("No folder open") { Spring = true, TextAlign = ContentAlignment.MiddleLeft };
    private readonly ToolStripStatusLabel _undoLabel = new(string.Empty);

    public MainForm(string? initialFolder)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(900, 600);
        Size = new Size(1180, 780);
        StartPosition = FormStartPosition.CenterScreen;

        var mainSplit = BuildLayout();
        var status = BuildStatusStrip();
        var tools = BuildToolStrip();
        var menu = BuildMenu();

        Controls.Add(mainSplit);
        Controls.Add(status);
        Controls.Add(tools);
        Controls.Add(menu);
        MainMenuStrip = menu;

        _debounce.Tick += (_, _) =>
        {
            _debounce.Stop();
            RebuildPreview();
        };

        _stepEditor.Changed += (_, _) =>
        {
            RefreshStepList(keepSelection: true);
            SchedulePreview();
        };

        foreach (var batch in UndoJournal.LoadAll())
        {
            _undo.Push(batch);
        }

        UpdateUndoState();
        RefreshStepList(keepSelection: false);

        if (!string.IsNullOrEmpty(initialFolder))
        {
            OpenFolder(initialFolder);
        }
        else
        {
            RebuildPreview();
        }
    }

    // ---- construction ----

    private SplitContainer BuildLayout()
    {
        _stepList.Columns.Add("#", 34);
        _stepList.Columns.Add("Step", 460);
        _stepList.SelectedIndexChanged += (_, _) =>
        {
            if (!_suppressStepEvents)
            {
                _stepEditor.Load(SelectedStep());
            }
        };
        _stepList.ItemChecked += (_, e) =>
        {
            if (_suppressStepEvents || e.Item.Index >= _rules.Steps.Count)
            {
                return;
            }

            _rules.Steps[e.Item.Index].Enabled = e.Item.Checked;
            SchedulePreview();
        };

        _preview.Columns.Add("#", 46, HorizontalAlignment.Right);
        _preview.Columns.Add("Current name", 330);
        _preview.Columns.Add("Proposed name", 330);
        _preview.Columns.Add("Status", 90);
        _preview.Columns.Add("Note", 240);
        _preview.RetrieveVirtualItem += OnRetrieveVirtualItem;

        var stepButtons = BuildStepButtons();

        var stepPanel = new Panel { Dock = DockStyle.Fill };
        stepPanel.Controls.Add(_stepList);
        stepPanel.Controls.Add(stepButtons);

        var topSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterWidth = 6,
        };
        topSplit.Panel1.Controls.Add(stepPanel);
        topSplit.Panel1.Controls.Add(new Label
        {
            Text = "Rule steps - applied top to bottom",
            Dock = DockStyle.Top,
            Height = 22,
            TextAlign = ContentAlignment.MiddleLeft,
            Padding = new Padding(6, 0, 0, 0),
            ForeColor = SystemColors.GrayText,
        });
        topSplit.Panel2.Controls.Add(_stepEditor);

        var previewPanel = new Panel { Dock = DockStyle.Fill };
        previewPanel.Controls.Add(_preview);
        previewPanel.Controls.Add(BuildPreviewHeader());

        var mainSplit = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Horizontal,
            SplitterWidth = 6,
        };
        mainSplit.Panel1.Controls.Add(topSplit);
        mainSplit.Panel2.Controls.Add(previewPanel);
        mainSplit.Panel1MinSize = 180;
        mainSplit.Panel2MinSize = 180;

        Load += (_, _) =>
        {
            TrySetSplitter(mainSplit, 300);
            TrySetSplitter(topSplit, 520);
        };

        return mainSplit;
    }

    private static void TrySetSplitter(SplitContainer container, int distance)
    {
        try
        {
            container.SplitterDistance = distance;
        }
        catch (InvalidOperationException)
        {
            // The window is too small for the preferred split; the default is fine.
        }
        catch (ArgumentOutOfRangeException)
        {
        }
    }

    private ToolStrip BuildStepButtons()
    {
        var strip = new ToolStrip
        {
            Dock = DockStyle.Bottom,
            GripStyle = ToolStripGripStyle.Hidden,
            RenderMode = ToolStripRenderMode.System,
        };

        var add = new ToolStripDropDownButton("Add step")
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        };
        foreach (var op in StepCatalog.All)
        {
            var captured = op;
            add.DropDownItems.Add(StepCatalog.DisplayName(op), null, (_, _) => AddStep(captured));
        }

        strip.Items.Add(add);
        strip.Items.Add(new ToolStripButton("Duplicate", null, (_, _) => DuplicateStep())
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        strip.Items.Add(new ToolStripButton("Remove", null, (_, _) => RemoveStep())
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        strip.Items.Add(new ToolStripSeparator());
        strip.Items.Add(new ToolStripButton("Move up", null, (_, _) => MoveStep(-1))
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        strip.Items.Add(new ToolStripButton("Move down", null, (_, _) => MoveStep(1))
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        return strip;
    }

    private ToolStrip BuildPreviewHeader()
    {
        var strip = new ToolStrip
        {
            Dock = DockStyle.Top,
            GripStyle = ToolStripGripStyle.Hidden,
            RenderMode = ToolStripRenderMode.System,
        };
        strip.Items.Add(new ToolStripLabel("Preview"));
        strip.Items.Add(new ToolStripSeparator());
        strip.Items.Add(new ToolStripLabel("Show:"));
        _filterBox.Items.AddRange(new object[] { "Everything", "Changes only", "Problems only" });
        _filterBox.SelectedIndex = 0;
        _filterBox.SelectedIndexChanged += (_, _) => RefreshPreviewList();
        strip.Items.Add(_filterBox);
        strip.Items.Add(new ToolStripSeparator());
        strip.Items.Add(new ToolStripButton("Export plan.json", null, (_, _) => ExportPlan())
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        return strip;
    }

    private ToolStrip BuildToolStrip()
    {
        var strip = new ToolStrip
        {
            GripStyle = ToolStripGripStyle.Hidden,
            RenderMode = ToolStripRenderMode.System,
        };
        strip.Items.Add(new ToolStripLabel("Folder:"));
        strip.Items.Add(_folderBox);
        strip.Items.Add(new ToolStripButton("Browse...", null, (_, _) => BrowseForFolder())
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        strip.Items.Add(new ToolStripButton("Reload", null, (_, _) => ReloadFolder())
        {
            DisplayStyle = ToolStripItemDisplayStyle.Text,
        });
        strip.Items.Add(new ToolStripSeparator());

        strip.Items.Add(new ToolStripLabel("Apply to:"));
        _applyToBox.Items.AddRange(new object[] { "Name only", "Name and extension" });
        _applyToBox.SelectedIndex = 0;
        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            SchedulePreview();
        };
        strip.Items.Add(_applyToBox);

        strip.Items.Add(new ToolStripLabel("Order:"));
        _sortBox.Items.AddRange(new object[] { "Name", "Created", "Modified" });
        _sortBox.SelectedIndex = 0;
        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = (SortMode)_sortBox.SelectedIndex;
            SchedulePreview();
        };
        strip.Items.Add(_sortBox);

        strip.Items.Add(new ToolStripSeparator());
        _applyButton.Click += (_, _) => ApplyRename();
        _undoButton.Click += (_, _) => UndoLastBatch();
        strip.Items.Add(_applyButton);
        strip.Items.Add(_undoButton);
        return strip;
    }

    private MenuStrip BuildMenu()
    {
        var menu = new MenuStrip();

        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add(new ToolStripMenuItem("&Open folder...", null, (_, _) => BrowseForFolder())
        {
            ShortcutKeys = Keys.Control | Keys.O,
        });
        file.DropDownItems.Add(new ToolStripMenuItem("&Reload folder", null, (_, _) => ReloadFolder())
        {
            ShortcutKeys = Keys.F5,
        });
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(new ToolStripMenuItem("&Load rules...", null, (_, _) => LoadRules())
        {
            ShortcutKeys = Keys.Control | Keys.L,
        });
        file.DropDownItems.Add(new ToolStripMenuItem("&Save rules...", null, (_, _) => SaveRules())
        {
            ShortcutKeys = Keys.Control | Keys.S,
        });
        file.DropDownItems.Add(new ToolStripMenuItem("&Export plan.json...", null, (_, _) => ExportPlan())
        {
            ShortcutKeys = Keys.Control | Keys.E,
        });
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add(new ToolStripMenuItem("E&xit", null, (_, _) => Close()));
        menu.Items.Add(file);

        var edit = new ToolStripMenuItem("&Steps");
        var addMenu = new ToolStripMenuItem("&Add");
        foreach (var op in StepCatalog.All)
        {
            var captured = op;
            addMenu.DropDownItems.Add(StepCatalog.DisplayName(op), null, (_, _) => AddStep(captured));
        }

        edit.DropDownItems.Add(addMenu);
        edit.DropDownItems.Add(new ToolStripMenuItem("D&uplicate", null, (_, _) => DuplicateStep()));
        edit.DropDownItems.Add(new ToolStripMenuItem("&Remove", null, (_, _) => RemoveStep()));
        edit.DropDownItems.Add(new ToolStripSeparator());
        edit.DropDownItems.Add(new ToolStripMenuItem("Move &up", null, (_, _) => MoveStep(-1)));
        edit.DropDownItems.Add(new ToolStripMenuItem("Move &down", null, (_, _) => MoveStep(1)));
        edit.DropDownItems.Add(new ToolStripSeparator());
        edit.DropDownItems.Add(new ToolStripMenuItem("&Clear all", null, (_, _) => ClearSteps()));
        menu.Items.Add(edit);

        var rename = new ToolStripMenuItem("&Rename");
        rename.DropDownItems.Add(new ToolStripMenuItem("&Apply", null, (_, _) => ApplyRename())
        {
            ShortcutKeys = Keys.Control | Keys.Enter,
        });
        rename.DropDownItems.Add(new ToolStripMenuItem("&Undo last batch", null, (_, _) => UndoLastBatch())
        {
            ShortcutKeys = Keys.Control | Keys.Z,
        });
        rename.DropDownItems.Add(new ToolStripSeparator());
        rename.DropDownItems.Add(new ToolStripMenuItem("Open folder in E&xplorer", null, (_, _) => OpenInExplorer()));
        menu.Items.Add(rename);

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add(new ToolStripMenuItem("&About", null, (_, _) => ShowAbout()));
        menu.Items.Add(help);

        return menu;
    }

    private StatusStrip BuildStatusStrip()
    {
        var status = new StatusStrip();
        status.Items.Add(_summaryLabel);
        status.Items.Add(_undoLabel);
        return status;
    }

    // ---- folder ----

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog
        {
            Description = "Choose the folder to rename files in",
            UseDescriptionForTitle = true,
            ShowNewFolderButton = false,
        };
        if (!string.IsNullOrEmpty(_folder) && Directory.Exists(_folder))
        {
            dialog.SelectedPath = _folder;
        }

        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            OpenFolder(dialog.SelectedPath);
        }
    }

    private void OpenFolder(string folder)
    {
        _folder = Path.GetFullPath(folder);
        _folderBox.Text = _folder;
        ReloadFolder();
    }

    private void ReloadFolder()
    {
        _scan.Clear();
        if (!string.IsNullOrEmpty(_folder))
        {
            try
            {
                _scan.AddRange(FileScanner.Scan(_folder));
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                ShowError("Cannot read the folder", ex.Message);
            }
        }

        RebuildPreview();
    }

    private void OpenInExplorer()
    {
        if (string.IsNullOrEmpty(_folder) || !Directory.Exists(_folder))
        {
            return;
        }

        try
        {
            Process.Start(new ProcessStartInfo("explorer.exe", "\"" + _folder + "\"") { UseShellExecute = true });
        }
        catch (Exception ex) when (ex is System.ComponentModel.Win32Exception or IOException)
        {
            ShowError("Cannot open Explorer", ex.Message);
        }
    }

    // ---- steps ----

    private RuleStep? SelectedStep()
    {
        var index = SelectedStepIndex();
        return index >= 0 && index < _rules.Steps.Count ? _rules.Steps[index] : null;
    }

    private int SelectedStepIndex() =>
        _stepList.SelectedIndices.Count > 0 ? _stepList.SelectedIndices[0] : -1;

    private void AddStep(StepOp op)
    {
        _rules.Steps.Add(StepCatalog.Create(op));
        RefreshStepList(keepSelection: false);
        SelectStep(_rules.Steps.Count - 1);
        SchedulePreview();
    }

    private void DuplicateStep()
    {
        var index = SelectedStepIndex();
        if (index < 0)
        {
            return;
        }

        _rules.Steps.Insert(index + 1, _rules.Steps[index].Clone());
        RefreshStepList(keepSelection: false);
        SelectStep(index + 1);
        SchedulePreview();
    }

    private void RemoveStep()
    {
        var index = SelectedStepIndex();
        if (index < 0)
        {
            return;
        }

        _rules.Steps.RemoveAt(index);
        RefreshStepList(keepSelection: false);
        SelectStep(Math.Min(index, _rules.Steps.Count - 1));
        SchedulePreview();
    }

    private void MoveStep(int delta)
    {
        var index = SelectedStepIndex();
        var target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count)
        {
            return;
        }

        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        RefreshStepList(keepSelection: false);
        SelectStep(target);
        SchedulePreview();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0)
        {
            return;
        }

        if (MessageBox.Show(this, "Remove every step from the rule set?", "Batch Rename Studio",
                MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        _rules.Steps.Clear();
        RefreshStepList(keepSelection: false);
        SchedulePreview();
    }

    private void SelectStep(int index)
    {
        if (index < 0 || index >= _stepList.Items.Count)
        {
            _stepEditor.Load(null);
            return;
        }

        _stepList.Items[index].Selected = true;
        _stepList.Items[index].Focused = true;
        _stepList.EnsureVisible(index);
        _stepEditor.Load(_rules.Steps[index]);
    }

    private void RefreshStepList(bool keepSelection)
    {
        var selected = keepSelection ? SelectedStepIndex() : -1;
        _suppressStepEvents = true;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            var step = _rules.Steps[i];
            var item = new ListViewItem((i + 1).ToString());
            item.SubItems.Add(step.Describe());
            item.Checked = step.Enabled;
            if (!step.Enabled)
            {
                item.ForeColor = SystemColors.GrayText;
            }

            _stepList.Items.Add(item);
        }

        _stepList.EndUpdate();
        _suppressStepEvents = false;

        if (selected >= 0 && selected < _stepList.Items.Count)
        {
            _stepList.Items[selected].Selected = true;
        }
        else if (_stepList.Items.Count == 0)
        {
            _stepEditor.Load(null);
        }
    }

    // ---- preview ----

    private void SchedulePreview()
    {
        _debounce.Stop();
        _debounce.Start();
    }

    private void RebuildPreview()
    {
        _plan = PlanBuilder.Build(_scan, _rules);
        RefreshPreviewList();
    }

    private void RefreshPreviewList()
    {
        _visible.Clear();
        var filter = (PreviewFilter)Math.Max(0, _filterBox.SelectedIndex);
        if (_plan != null)
        {
            for (var i = 0; i < _plan.Items.Count; i++)
            {
                var status = _plan.Items[i].Status;
                var keep = filter switch
                {
                    PreviewFilter.ChangesOnly => status == PlanStatus.Ok,
                    PreviewFilter.ProblemsOnly => status is PlanStatus.Collision or PlanStatus.Invalid,
                    _ => true,
                };
                if (keep)
                {
                    _visible.Add(i);
                }
            }
        }

        _preview.SelectedIndices.Clear();
        _preview.VirtualListSize = _visible.Count;
        _preview.Invalidate();
        UpdateSummary();
    }

    private void OnRetrieveVirtualItem(object? sender, RetrieveVirtualItemEventArgs e)
    {
        if (_plan == null || e.ItemIndex < 0 || e.ItemIndex >= _visible.Count)
        {
            e.Item = new ListViewItem(string.Empty);
            return;
        }

        var index = _visible[e.ItemIndex];
        var item = _plan.Items[index];
        var row = new ListViewItem((index + 1).ToString());
        row.SubItems.Add(item.Original);
        row.SubItems.Add(item.Proposed);
        row.SubItems.Add(item.Status);
        row.SubItems.Add(item.Reason);
        row.UseItemStyleForSubItems = true;
        switch (item.Status)
        {
            case PlanStatus.Collision:
                row.BackColor = Color.FromArgb(255, 226, 226);
                break;
            case PlanStatus.Invalid:
                row.BackColor = Color.FromArgb(255, 236, 205);
                break;
            case PlanStatus.Unchanged:
                row.ForeColor = SystemColors.GrayText;
                break;
            default:
                row.BackColor = Color.FromArgb(226, 245, 227);
                break;
        }

        e.Item = row;
    }

    private void UpdateSummary()
    {
        if (string.IsNullOrEmpty(_folder))
        {
            _summaryLabel.Text = "No folder open - use File > Open folder";
            _applyButton.Enabled = false;
            return;
        }

        var summary = _plan?.Summary ?? new PlanSummary();
        _summaryLabel.Text =
            $"{summary.Total} file(s)  |  {summary.Ok} to rename, {summary.Unchanged} unchanged, " +
            $"{summary.Collision} collision, {summary.Invalid} invalid" +
            (_visible.Count != summary.Total ? $"  |  showing {_visible.Count}" : string.Empty);
        _applyButton.Enabled = summary.Ok > 0;
    }

    private void UpdateUndoState()
    {
        _undoButton.Enabled = _undo.Count > 0;
        _undoLabel.Text = _undo.Count > 0
            ? $"Undo available: {_undo.Count} batch(es)"
            : "Nothing to undo";
    }

    // ---- rules files ----

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            var loaded = RuleSetJson.Load(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            _applyToBox.SelectedIndex = _rules.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
            _sortBox.SelectedIndex = (int)_rules.Sort;
            RefreshStepList(keepSelection: false);
            SelectStep(_rules.Steps.Count > 0 ? 0 : -1);
            RebuildPreview();
        }
        catch (Exception ex) when (ex is RuleFormatException or IOException or UnauthorizedAccessException)
        {
            ShowError("Cannot load these rules", ex.Message);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            RuleSetJson.Save(dialog.FileName, _rules);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            ShowError("Cannot save these rules", ex.Message);
        }
    }

    private void ExportPlan()
    {
        if (_plan == null || string.IsNullOrEmpty(_folder))
        {
            ShowError("Nothing to export", "Open a folder first.");
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "Export plan",
            Filter = "Plans (*.json)|*.json",
            FileName = "plan.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            PlanJson.Write(dialog.FileName, _plan);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            ShowError("Cannot export the plan", ex.Message);
        }
    }

    // ---- apply and undo ----

    private void ApplyRename()
    {
        if (string.IsNullOrEmpty(_folder) || !Directory.Exists(_folder))
        {
            ShowError("No folder", "Open a folder first.");
            return;
        }

        // Re-scan first: the folder may have changed since the preview was built.
        ReloadFolder();
        var plan = _plan;
        if (plan == null || plan.Summary.Ok == 0)
        {
            ShowError("Nothing to rename", "No file has a valid new name that differs from its current one.");
            return;
        }

        var message = new StringBuilder();
        message.AppendLine($"Rename {plan.Summary.Ok} file(s) in:");
        message.AppendLine(_folder);
        message.AppendLine();
        if (plan.Summary.Collision > 0 || plan.Summary.Invalid > 0)
        {
            message.AppendLine(
                $"{plan.Summary.Collision} collision(s) and {plan.Summary.Invalid} invalid name(s) will be skipped.");
            message.AppendLine();
        }

        message.Append("Continue?");

        if (MessageBox.Show(this, message.ToString(), "Apply rename", MessageBoxButtons.OKCancel,
                MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        RenameResult result;
        Cursor = Cursors.WaitCursor;
        try
        {
            result = RenameExecutor.Apply(_folder, plan);
        }
        finally
        {
            Cursor = Cursors.Default;
        }

        if (result.Renamed > 0)
        {
            UndoJournal.TrySave(result.Batch);
            _undo.Push(result.Batch);
            UpdateUndoState();
        }

        ReloadFolder();

        if (result.Failures.Count > 0)
        {
            ShowError(
                $"Renamed {result.Renamed} file(s), {result.Failures.Count} failed",
                Describe(result.Failures));
        }
        else
        {
            MessageBox.Show(this, $"Renamed {result.Renamed} file(s).", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
        }
    }

    private void UndoLastBatch()
    {
        if (_undo.Count == 0)
        {
            return;
        }

        var batch = _undo.Peek();
        var question =
            $"Undo {batch.Operations.Count} rename(s) in:{Environment.NewLine}{batch.Directory}{Environment.NewLine}{Environment.NewLine}Continue?";
        if (MessageBox.Show(this, question, "Undo rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question)
            != DialogResult.OK)
        {
            return;
        }

        _undo.Pop();
        IReadOnlyList<RenameFailure> failures;
        Cursor = Cursors.WaitCursor;
        try
        {
            failures = RenameExecutor.Undo(batch);
        }
        finally
        {
            Cursor = Cursors.Default;
        }

        UndoJournal.Discard(batch);
        UpdateUndoState();

        if (string.Equals(batch.Directory, _folder, StringComparison.OrdinalIgnoreCase))
        {
            ReloadFolder();
        }

        if (failures.Count > 0)
        {
            ShowError($"{failures.Count} file(s) could not be restored", Describe(failures));
        }
    }

    private static string Describe(IReadOnlyList<RenameFailure> failures)
    {
        var text = new StringBuilder();
        foreach (var failure in failures.Take(15))
        {
            text.AppendLine($"{failure.Name}: {failure.Message}");
        }

        if (failures.Count > 15)
        {
            text.AppendLine($"... and {failures.Count - 15} more");
        }

        return text.ToString();
    }

    // ---- misc ----

    private void ShowAbout()
    {
        var text = new StringBuilder();
        text.AppendLine("Batch Rename Studio");
        text.AppendLine();
        text.AppendLine("Preview-first batch renaming. Nothing is written to disk until");
        text.AppendLine("you press Apply, and the last batches can always be undone.");
        text.AppendLine();
        text.AppendLine("Headless planning:");
        text.AppendLine("  BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
        MessageBox.Show(this, text.ToString(), "About", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }

    private void ShowError(string caption, string detail) =>
        MessageBox.Show(this, detail, caption, MessageBoxButtons.OK, MessageBoxIcon.Warning);

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            _debounce.Dispose();
        }

        base.Dispose(disposing);
    }
}

