55	/// <summary>
56	/// One step of a rule set. A single mutable class carries the union of all six
57	/// operations' fields; only the fields relevant to <see cref="Op"/> are read.
58	/// That keeps the GUI editor, the JSON reader and the engine on one shape.
59	/// </summary>
60	public sealed class RuleStep
61	{
62	    public StepOp Op { get; set; } = StepOp.Replace;
63	
64	    /// <summary>
65	    /// GUI-only convenience: a step can be muted without deleting it.
66	    /// Absent from the JSON contract; defaults to true when the key is missing.
67	    /// </summary>
68	    public bool Enabled { get; set; } = true;
69	
70	    // replace
71	    public string Find { get; set; } = string.Empty;
72	    public string ReplaceWith { get; set; } = string.Empty;
73	    public bool Regex { get; set; }
74	    public bool IgnoreCase { get; set; }
75	
76	    // insert
77	    public string Text { get; set; } = string.Empty;
78	    public InsertPosition InsertPosition { get; set; } = InsertPosition.Prefix;
79	    public int Index { get; set; }
80	
81	    // remove
82	    public int From { get; set; }
83	    public int Count { get; set; }
84	
85	    // sequence
86	    public string Pattern { get; set; } = "{n:000}_";
87	    public int Start { get; set; } = 1;
88	    public int Step { get; set; } = 1;
89	    public NumberPosition NumberPosition { get; set; } = NumberPosition.Prefix;
90	
91	    // case
92	    public CaseMode CaseMode { get; set; } = CaseMode.Upper;
93	
94	    // extension
95	    public ExtensionMode ExtensionMode { get; set; } = ExtensionMode.Lower;
96	    public string Value { get; set; } = string.Empty;
97	
98	    public RuleStep Clone() => (RuleStep)MemberwiseClone();
99	
100	    /// <summary>One-line human summary used by the step list in the GUI.</summary>
101	    public string Describe()
102	    {
103	        switch (Op)
104	        {
105	            case StepOp.Replace:
106	                var mode = Regex ? "regex" : "text";
107	                var ic = IgnoreCase ? ", ignore case" : string.Empty;
108	                return $"Replace ({mode}{ic}): \"{Find}\" → \"{ReplaceWith}\"";
109	            case StepOp.Insert:
110	                return InsertPosition switch
111	                {
112	                    InsertPosition.Prefix => $"Insert \"{Text}\" at start",
113	                    InsertPosition.Suffix => $"Insert \"{Text}\" at end",
114	                    _ => $"Insert \"{Text}\" at index {Index}",
115	                };
116	            case StepOp.Remove:
117	                return $"Remove {Count} char(s) from index {From}";
118	            case StepOp.Sequence:
119	                var where = NumberPosition == NumberPosition.Prefix ? "start" : "end";
120	                return $"Number \"{Pattern}\" at {where} (start {Start}, step {Step})";
121	            case StepOp.Case:
122	                return $"Case: {CaseMode.ToString().ToLowerInvariant()}";
123	            case StepOp.Extension:
124	                return ExtensionMode == ExtensionMode.Set
125	                    ? $"Extension: set to \"{Value}\""
126	                    : $"Extension: {ExtensionMode.ToString().ToLowerInvariant()}";
127	            default:
128	                return Op.ToString();
129	        }
130	    }
131	}
