2	using System.Text;
3	using System.Text.RegularExpressions;
4	
5	namespace BatchRenameStudio.Core;
6	
7	/// <summary>
8	/// Pure string transformations for the six operations. No file system access,
9	/// no culture sensitivity: every comparison and casing call is ordinal or
10	/// invariant so that the same inputs always produce the same output.
11	/// </summary>
12	public static class StepEngine
13	{
14	    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);
15	
16	    private static readonly Regex SequenceToken =
17	        new(@"\{n:(0+)\}", RegexOptions.CultureInvariant | RegexOptions.Compiled);
18	
19	    /// <summary>
20	    /// Applies every enabled step of <paramref name="rules"/> to one file name.
21	    /// <paramref name="ordinal"/> is the 0-based position of the file in
22	    /// processing order and drives the sequence counter.
23	    /// </summary>
24	    public static string ApplyAll(string fileName, RuleSet rules, int ordinal)
25	    {
26	        if (rules.ApplyTo == ApplyTo.NameAndExtension)
27	        {
28	            var whole = fileName;
29	            foreach (var step in rules.Steps)
30	            {
31	                if (!step.Enabled)
32	                {
33	                    continue;
34	                }
35	
36	                whole = step.Op == StepOp.Extension
37	                    ? ApplyExtensionToWhole(whole, step)
38	                    : ApplyToTarget(whole, step, ordinal);
39	            }
40	
41	            // Rule 12: under nameAndExtension the target string IS the proposed name.
42	            return whole;
43	        }
44	
45	        var parts = NameParts.Split(fileName);
46	        foreach (var step in rules.Steps)
47	        {
48	            if (!step.Enabled)
49	            {
50	                continue;
51	            }
52	
53	            parts = step.Op == StepOp.Extension
54	                ? parts.WithExtension(ApplyExtension(parts.Extension, step))
55	                : parts.WithBase(ApplyToTarget(parts.Base, step, ordinal));
56	        }
57	
58	        return parts.Compose();
59	    }
60	
61	    /// <summary>Counter value for the file at <paramref name="ordinal"/>.</summary>
62	    public static int SequenceValue(RuleStep step, int ordinal) => step.Start + (step.Step * ordinal);
63	
64	    /// <summary>Applies a non-extension step to the current target string.</summary>
65	    public static string ApplyToTarget(string target, RuleStep step, int ordinal) => step.Op switch
66	    {
67	        StepOp.Replace => ApplyReplace(target, step),
68	        StepOp.Insert => ApplyInsert(target, step),
69	        StepOp.Remove => ApplyRemove(target, step),
70	        StepOp.Sequence => ApplySequence(target, step, ordinal),
71	        StepOp.Case => ApplyCase(target, step),
72	        StepOp.Extension => target, // handled by the caller
73	        _ => target,
74	    };
75	
76	    private static string ApplyReplace(string target, RuleStep step)
77	    {
78	        if (step.Find.Length == 0)
79	        {
80	            // An empty needle has no well-defined "all occurrences"; treat as a no-op.
81	            return target;
82	        }
83	
84	        if (step.Regex)
85	        {
86	            var options = RegexOptions.CultureInvariant;
87	            if (step.IgnoreCase)
88	            {
89	                options |= RegexOptions.IgnoreCase;
90	            }
91	
92	            try
93	            {
94	                return Regex.Replace(target, step.Find, step.ReplaceWith, options, RegexTimeout);
95	            }
96	            catch (RegexMatchTimeoutException)
97	            {
98	                return target;
99	            }
100	        }
101	
102	        var comparison = step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
103	        return target.Replace(step.Find, step.ReplaceWith, comparison);
104	    }
105	
106	    private static string ApplyInsert(string target, RuleStep step)
107	    {
108	        switch (step.InsertPosition)
109	        {
110	            case InsertPosition.Prefix:
111	                return step.Text + target;
112	            case InsertPosition.Suffix:
113	                return target + step.Text;
114	            default:
115	                var at = Math.Clamp(step.Index, 0, target.Length);
116	                return target.Insert(at, step.Text);
117	        }
118	    }
119	
120	    private static string ApplyRemove(string target, RuleStep step)
121	    {
122	        var from = Math.Clamp(step.From, 0, target.Length);
123	        var count = Math.Clamp(step.Count, 0, target.Length - from);
124	        return count == 0 ? target : target.Remove(from, count);
125	    }
126	
127	    private static string ApplySequence(string target, RuleStep step, int ordinal)
128	    {
129	        var rendered = RenderSequence(step, SequenceValue(step, ordinal));
130	        return step.NumberPosition == NumberPosition.Suffix
131	            ? target + rendered
132	            : rendered + target;
133	    }
134	
135	    /// <summary>
136	    /// Renders the pattern, substituting <c>{n:000}</c> with the zero-padded
137	    /// counter. A pattern without a token is used verbatim.
138	    /// </summary>
139	    public static string RenderSequence(RuleStep step, int value) =>
140	        SequenceToken.Replace(
141	            step.Pattern,
142	            m => value.ToString(new string('0', m.Groups[1].Value.Length), CultureInfo.InvariantCulture));
143	
144	    private static string ApplyCase(string target, RuleStep step) => step.CaseMode switch
145	    {
146	        CaseMode.Upper => target.ToUpperInvariant(),
147	        CaseMode.Lower => target.ToLowerInvariant(),
148	        _ => ToTitle(target),
149	    };
150	
151	    /// <summary>
152	    /// For every maximal run of Unicode letters: first character uppercased,
153	    /// the rest lowercased. Everything else is copied through untouched.
154	    /// </summary>
155	    private static string ToTitle(string target)
156	    {
157	        var sb = new StringBuilder(target.Length);
158	        var inRun = false;
159	        foreach (var ch in target)
160	        {
161	            if (char.IsLetter(ch))
162	            {
163	                sb.Append(inRun ? char.ToLowerInvariant(ch) : char.ToUpperInvariant(ch));
164	                inRun = true;
165	            }
166	            else
167	            {
168	                sb.Append(ch);
169	                inRun = false;
170	            }
171	        }
172	
173	        return sb.ToString();
174	    }
175	
176	    /// <summary>Transforms an extension (no leading dot) per an extension step.</summary>
177	    public static string ApplyExtension(string extension, RuleStep step) => step.ExtensionMode switch
178	    {
179	        ExtensionMode.Lower => extension.ToLowerInvariant(),
180	        ExtensionMode.Upper => extension.ToUpperInvariant(),
181	        _ => step.Value,
182	    };
183	
184	    /// <summary>
185	    /// Rule 11/12 under <c>applyTo:"nameAndExtension"</c>: the extension step
186	    /// applies to the trailing extension of the current whole string.
187	    /// </summary>
188	    private static string ApplyExtensionToWhole(string whole, RuleStep step)
189	    {
190	        var parts = NameParts.Split(whole);
191	        return parts.WithExtension(ApplyExtension(parts.Extension, step)).Compose();
192	    }
193	}

