7	namespace BatchRenameStudio.Core;
8	
9	/// <summary>Reader and writer for the <c>rules.json</c> contract.</summary>
10	public static class RuleSetJson
11	{
12	    private static readonly JsonDocumentOptions DocumentOptions = new()
13	    {
14	        AllowTrailingCommas = true,
15	        CommentHandling = JsonCommentHandling.Skip,
16	    };
17	
18	    public static RuleSet Load(string path)
19	    {
20	        string text;
21	        try
22	        {
23	            text = File.ReadAllText(path);
24	        }
25	        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
26	        {
27	            throw new RuleFormatException($"Cannot read rules file '{path}': {ex.Message}");
28	        }
29	
30	        return Parse(text);
31	    }
