33	    public static RuleSet Parse(string json)
34	    {
35	        JsonDocument document;
36	        try
37	        {
38	            document = JsonDocument.Parse(json, DocumentOptions);
39	        }
40	        catch (JsonException ex)
41	        {
42	            throw new RuleFormatException($"rules.json is not valid JSON: {ex.Message}");
43	        }
44	
45	        using (document)
46	        {
47	            var root = document.RootElement;
48	            if (root.ValueKind != JsonValueKind.Object)
49	            {
50	                throw new RuleFormatException("rules.json must contain a JSON object at the root.");
51	            }
52	
53	            var rules = new RuleSet
54	            {
55	                ApplyTo = ReadApplyTo(root),
56	                Sort = ReadSort(root),
57	            };
58	
59	            if (root.TryGetProperty("steps", out var steps))
60	            {
61	                if (steps.ValueKind != JsonValueKind.Array)
62	                {
63	                    throw new RuleFormatException("\"steps\" must be an array.");
64	                }
65	
66	                var index = 0;
67	                foreach (var element in steps.EnumerateArray())
68	                {
69	                    rules.Steps.Add(ReadStep(element, index));
70	                    index++;
71	                }
72	            }
73	
74	            return rules;
75	        }
76	    }
77	
78	    private static ApplyTo ReadApplyTo(JsonElement root)
79	    {
80	        var value = ReadString(root, "applyTo") ?? "name";
81	        return value.ToLowerInvariant() switch
82	        {
83	            "name" => ApplyTo.Name,
84	            "nameandextension" => ApplyTo.NameAndExtension,
85	            _ => throw new RuleFormatException($"Unknown applyTo value \"{value}\"."),
86	        };
87	    }
88	
89	    private static SortMode ReadSort(JsonElement root)
90	    {
91	        var value = ReadString(root, "sort") ?? "name";
92	        return value.ToLowerInvariant() switch
93	        {
94	            "name" => SortMode.Name,
95	            "created" => SortMode.Created,
96	            "modified" => SortMode.Modified,
97	            _ => throw new RuleFormatException($"Unknown sort value \"{value}\"."),
98	        };
99	    }
