using System.Text;

namespace BatchRenameStudio.Ui;

/// <summary>
/// A desktop tool must never vanish without a word. Anything that escapes the
/// UI thread is written to a log next to the undo journal and shown to the
/// user, so a failure can always be reported with something concrete.
/// </summary>
internal static class CrashReporter
{
    public static string LogPath =>
        Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "BatchRenameStudio",
            "crash.log");

    public static void Install()
    {
        Application.ThreadException += (_, e) => Report(e.Exception, fatal: false);
        AppDomain.CurrentDomain.UnhandledException += (_, e) =>
        {
            if (e.ExceptionObject is Exception ex)
            {
                Report(ex, fatal: true);
            }
        };
    }

    public static void Report(Exception exception, bool fatal)
    {
        var path = TryWriteLog(exception);
        var text = new StringBuilder();
        text.AppendLine(fatal
            ? "Batch Rename Studio has to close because of an unexpected error."
            : "Something went wrong. The application is still running.");
        text.AppendLine();
        text.AppendLine(exception.GetType().Name + ": " + exception.Message);
        if (path != null)
        {
            text.AppendLine();
            text.AppendLine("Details were written to:");
            text.AppendLine(path);
        }

        try
        {
            MessageBox.Show(text.ToString(), "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        catch (Exception ex) when (ex is InvalidOperationException or ObjectDisposedException)
        {
            // No message pump left; the log file is the record that remains.
        }
    }

    private static string? TryWriteLog(Exception exception)
    {
        try
        {
            var path = LogPath;
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            var entry = new StringBuilder();
            entry.AppendLine("---- " + DateTime.Now.ToString("u") + " ----");
            entry.AppendLine(exception.ToString());
            entry.AppendLine();
            File.AppendAllText(path, entry.ToString(), new UTF8Encoding(false));
            return path;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return null;
        }
    }
}

