namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        if (CommandLine.IsHeadless(args))
        {
            ConsoleBridge.Ensure();
            try
            {
                return CliRunner.Run(args);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine(ex.Message);
                return ExitCode.Failure;
            }
        }

        ApplicationConfiguration.Initialize();

        // The first non-option argument, when it is a folder, opens straight away.
        var initialFolder = args.FirstOrDefault(a =>
            !a.StartsWith("--", StringComparison.Ordinal) && Directory.Exists(a));

        Application.Run(new MainForm(initialFolder));
        return 0;
    }
}

