using BatchRenameStudio.Core;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Builds the real window against a throw-away folder, adds one step of every
/// kind and checks that the preview follows. It catches wiring and layout
/// failures - the kind that only show up once controls actually get a handle -
/// without a human having to watch. The window is shown briefly while it runs.
/// </summary>
internal static class UiSmokeTest
{
    public static int Run()
    {
        var folder = Path.Combine(Path.GetTempPath(), "brs-uismoke-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(folder);
        var failures = 0;

        try
        {
            foreach (var name in new[] { "alpha.TXT", "beta.txt", "gamma.md", "README" })
            {
                File.WriteAllText(Path.Combine(folder, name), "x");
            }

            ApplicationConfiguration.Initialize();

            using var form = new MainForm(folder);
            form.WindowState = FormWindowState.Minimized;
            form.ShowInTaskbar = false;
            form.Show();
            Pump();

            failures += Check(form.CurrentPlan != null, "the preview has a plan after opening a folder");
            failures += Check(form.CurrentPlan?.Items.Count == 4, "the plan lists all four files");
            failures += Check(form.VisibleRowCount == 4, "the preview shows all four rows");

            foreach (var op in StepCatalog.All)
            {
                form.AddStep(op);
                form.SelectStep(form.StepCount - 1);
                Pump();
                failures += Check(true, $"the editor accepts a \"{StepCatalog.DisplayName(op)}\" step");
            }

            form.RebuildPreview();
            Pump();
            failures += Check(form.StepCount == StepCatalog.All.Length, "every step stayed in the rule set");
            failures += Check(form.CurrentPlan?.Items.Count == 4, "the preview still covers every file");
            failures += Check(
                form.CurrentPlan?.Summary.Total == 4,
                "the summary still counts every file");

            form.Close();
            Pump();
        }
        catch (Exception ex)
        {
            Console.WriteLine("  FAIL the window threw " + ex.GetType().Name + ": " + ex.Message);
            Console.WriteLine(ex.StackTrace);
            failures++;
        }
        finally
        {
            try
            {
                Directory.Delete(folder, recursive: true);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                // Leftover temporary folders are harmless.
            }
        }

        Console.WriteLine(failures == 0 ? "ui smoke test passed" : $"ui smoke test failed ({failures})");
        return failures == 0 ? ExitCode.Success : ExitCode.Failure;
    }

    private static void Pump()
    {
        for (var i = 0; i < 3; i++)
        {
            Application.DoEvents();
        }
    }

    private static int Check(bool condition, string message)
    {
        Console.WriteLine((condition ? "  ok   " : "  FAIL ") + message);
        return condition ? 0 : 1;
    }
}

