// ---- applying and undoing a plan (the GUI's Apply / Undo path) ----

private static void RenameCases(string root)
{
    Section("rename and undo");

    var folder = NewFolder(root, "rename");
    foreach (var name in new[] { "a.txt", "b.txt", "c.txt" })
    {
        File.WriteAllText(Path.Combine(folder, name), "x");
    }

    var rules = RuleSetJson.Parse(
        """{"steps":[{"op":"sequence","pattern":"{n:00}_","start":1,"step":1,"position":"prefix"}]}""");

    var result = RenameExecutor.Apply(folder, PlanBuilder.Build(folder, rules));
    Check(result.Failures.Count == 0, "applying a clean plan reports no failure");
    Check(result.Renamed == 3, "all three files were renamed");
    Check(NamesIn(folder).SequenceEqual(new[] { "01_a.txt", "02_b.txt", "03_c.txt" }), "the new names are on disk");

    var undoFailures = RenameExecutor.Undo(result.Batch);
    Check(undoFailures.Count == 0, "undo reports no failure");
    Check(NamesIn(folder).SequenceEqual(new[] { "a.txt", "b.txt", "c.txt" }), "undo restored the original names");

    // Only "ok" items are touched.
    var blocked = NewFolder(root, "blocked");
    File.WriteAllText(Path.Combine(blocked, "a.txt"), "x");
    File.WriteAllText(Path.Combine(blocked, "b.txt"), "x");
    var collidingPlan = PlanBuilder.Build(
        blocked,
        RuleSetJson.Parse("""{"steps":[{"op":"replace","find":"a","replaceWith":"b"}]}"""));
    var blockedResult = RenameExecutor.Apply(blocked, collidingPlan);
    Check(blockedResult.Renamed == 0, "a plan of nothing but collisions renames nothing");
    Check(NamesIn(blocked).SequenceEqual(new[] { "a.txt", "b.txt" }), "the folder is untouched");

    // A rename that only changes casing.
    var casing = NewFolder(root, "casing");
    File.WriteAllText(Path.Combine(casing, "case.txt"), "x");
    var casingResult = RenameExecutor.Apply(
        casing,
        PlanBuilder.Build(casing, RuleSetJson.Parse("""{"steps":[{"op":"case","mode":"upper"}]}""")));
    Check(casingResult.Failures.Count == 0, "a case-only rename succeeds");
    Check(NamesIn(casing).SequenceEqual(new[] { "CASE.txt" }), "the casing on disk really changed");
    RenameExecutor.Undo(casingResult.Batch);
    Check(NamesIn(casing).SequenceEqual(new[] { "case.txt" }), "undo restores the original casing");

    // The journal survives a round trip through disk.
    var journalFolder = NewFolder(root, "journal");
    File.WriteAllText(Path.Combine(journalFolder, "j.txt"), "x");
    var journalResult = RenameExecutor.Apply(
        journalFolder,
        PlanBuilder.Build(
            journalFolder,
            RuleSetJson.Parse("""{"steps":[{"op":"insert","text":"kept-","position":"prefix"}]}""")));
    var saved = UndoJournal.TrySave(journalResult.Batch);
    Check(saved != null, "the batch was written to the undo journal");
    var reloaded = UndoJournal.LoadAll().FirstOrDefault(b => b.JournalPath == saved);
    Check(reloaded != null && reloaded.Operations.Count == 1, "the batch reloads from the journal");
    if (reloaded != null)
    {
        RenameExecutor.Undo(reloaded);
        UndoJournal.Discard(reloaded);
    }

    Check(NamesIn(journalFolder).SequenceEqual(new[] { "j.txt" }), "undo from the reloaded journal works");
    Check(saved == null || !File.Exists(saved), "the journal entry was cleaned up");
}

private static string[] NamesIn(string folder) =>
    Directory.GetFiles(folder)
        .Select(p => Path.GetFileName(p) ?? string.Empty)
        .OrderBy(n => n, StringComparer.Ordinal)
        .ToArray();

// ---- harness ----

